          { id: "d", text: "\u4ED6\u62C5\u5FC3\u8EAB\u4F53\u51FA\u95EE\u9898", isObservation: false },
          { id: "e", text: "\u4ED6\u809D\u706B\u65FA", isObservation: false },
          { id: "f", text: "\u4ED6\u4E0A\u706B\u4E86", isObservation: false }
