        principle: '\u53E3\u6E34\u8981\u5206"\u7F3A\u6C34"\u548C"\u6C34\u9001\u4E0D\u5230"\uFF1A\u8865\u6C34\u80FD\u89E3\u662F\u771F\u7F3A\u6C34\uFF1B\u8D8A\u559D\u8D8A\u6E34\u3001\u559D\u6C34\u80C3\u80C0\uFF0C\u5F80\u5F80\u662F\u6C34\u6DB2\u8F93\u5E03\u51FA\u4E86\u95EE\u9898\u3002\u540C\u6837\u662F\u6E34\uFF0C\u4E00\u4E2A\u8981"\u52A0\u6C34"\uFF0C\u4E00\u4E2A\u8981"\u901A\u6C34\u7BA1"\uFF0C\u65B9\u5411\u5B8C\u5168\u4E0D\u540C\u3002',
