            O("b", "\u80BA\u7684\u7CFB\u7EDF\uFF1A\u56E0\u4E3A\u6C14\u77ED\u4E4F\u529B", false, "\u4E4F\u529B\u4E0D\u7B49\u4E8E\u80BA\u7684\u95EE\u9898\uFF0C\u98DF\u6B32\u5DEE+\u8179\u80C0+\u4FBF\u7A00\u662F\u6D88\u5316\u5438\u6536\uFF08\u813E\uFF09\u7684\u7EBF\u7D22\u7EC4\u5408\u3002"),
            O("c", "\u662F\u80C3\u5728\u7269\u7406\u4E0A\u574F\u4E86", false, '\u4E2D\u533B\u810F\u8151\u662F\u529F\u80FD\u7CFB\u7EDF\u6982\u5FF5\uFF0C\u4E0D\u662F\u89E3\u5256\u5668\u5B98\u7684"\u574F\u4E86"\u3002'),
            O("d", "\u8FD9\u4E9B\u75C7\u72B6\u4E92\u4E0D\u76F8\u5173\uFF0C\u51D1\u5DE7\u540C\u65F6\u51FA\u73B0", false, "\u6B63\u662F\u628A\u6563\u843D\u7EBF\u7D22\u7EC4\u5408\u6210\u6574\u4F53\uFF08\u8FD0\u5316\u529F\u80FD\u51CF\u5F31\uFF09\uFF0C\u624D\u662F\u89C2\u5BDF\u7684\u4EF7\u503C\u3002")
