            O("b", "\u540E\u52E4\u5C31\u662F\u7BA1\u4ED3\u5E93\u7684\u90A3\u4E2A\u4EBA\uFF0C\u6362\u6389\u4ED6\u5C31\u884C", false, '\u628A\u529F\u80FD\u7CFB\u7EDF\u5F52\u7ED3\u4E3A\u5355\u4E00\u4E2A\u4EBA/\u5668\u5B98\uFF0C\u6B63\u662F"\u89E3\u5256\u5316"\u7684\u8BEF\u8BFB\u3002'),
            O("c", "\u91C7\u8D2D\u6162\u662F\u91C7\u8D2D\u7684\u95EE\u9898\uFF0C\u548C\u914D\u9001\u65E0\u5173", false, "\u5272\u88C2\u529F\u80FD\u7CFB\u7EDF\u5185\u7684\u76F8\u4E92\u5173\u8054\u3002"),
            O("d", "\u540E\u52E4\u95EE\u9898\u548C\u813E\u6CA1\u6709\u53EF\u6BD4\u6027", false, '"\u529F\u80FD\u7CFB\u7EDF"\u7684\u89C2\u5BDF\u6846\u67B6\u662F\u901A\u7528\u7684\u3002')
