          whyItMatters: "\u4E0D\u7406\u89E3\u4E2D\u533B\u7684\u601D\u7EF4\u65B9\u5F0F\uFF0C\u5C31\u7528\u4E2D\u533B\u7684\u6846\u67B6\u53BB\u7406\u89E3\u4EBA\u4F53\u548C\u75BE\u75C5\u3002",
          beginnerExplanation: '\u4E2D\u533B\u770B\u75C5\u5F88\u50CF\u662F\u4FA6\u63A2\u7834\u6848\uFF1A\u4FA6\u63A2\u4E0D\u770B"\u662F\u4EC0\u4E48\u7F6A"\uFF0C\u800C\u662F\u6536\u96C6\u7EBF\u7D22\u2014\u2014\u811A\u5370\u3001\u6307\u7EB9\u3001\u65F6\u95F4\u7EBF\u2014\u2014\u7136\u540E\u63A8\u7406\u51FA\u53D1\u751F\u4E86\u4EC0\u4E48\u3002\u4E2D\u533B\u4E5F\u662F\uFF0C\u5B83\u6536\u96C6\u4F60\u7684\u820C\u5934\u957F\u4EC0\u4E48\u6837\u3001\u8109\u8DF3\u5F97\u600E\u4E48\u6837\u3001\u4F60\u6015\u51B7\u8FD8\u662F\u6015\u70ED\uFF0C\u7136\u540E\u7528\u8FD9\u4E9B\u7EBF\u7D22"\u63A8\u7406"\u51FA\u4F60\u8EAB\u4F53\u5185\u90E8\u7684\u72B6\u6001\u3002',
          deeperExplanation: '\u4E2D\u533B\u7684\u6838\u5FC3\u601D\u7EF4\u65B9\u5F0F\u53EF\u6982\u62EC\u4E3A\u4E09\u4E2A\u5C42\u6B21\uFF1A\u4E00\u662F"\u53F8\u5916\u63E3\u5185"\uFF0C\u901A\u8FC7\u5916\u90E8\u5F81\u8C61\u63A8\u6D4B\u5185\u90E8\u75C5\u7406\u53D8\u5316\uFF0C\u8FD9\u5728\u300A\u7075\u67A2\xB7\u5916\u63E3\u300B\u4E2D\u5DF2\u6709\u660E\u786E\u8BBA\u8FF0\uFF1B\u4E8C\u662F"\u63F4\u7269\u6BD4\u7C7B"\uFF0C\u7528\u81EA\u7136\u754C\u4E2D\u5DF2\u77E5\u7684\u4E8B\u7269\u89C4\u5F8B\u6765\u7C7B\u6BD4\u4EBA\u4F53\u7684\u751F\u7406\u75C5\u7406\uFF0C\u5982\u7528\u6C34\u7684\u5BD2\u70ED\u53D8\u5316\u7C7B\u6BD4\u4EBA\u4F53\u7684\u5BD2\u70ED\u72B6\u6001\uFF1B\u4E09\u662F"\u52A8\u9759\u76F8\u53EC"\uFF0C\u8BA4\u4E3A\u4EBA\u4F53\u5904\u4E8E\u52A8\u6001\u53D8\u5316\u4E4B\u4E2D\uFF0C\u540C\u4E00\u4EBA\u4E0D\u540C\u65F6\u95F4\u7684\u72B6\u6001\u4E0D\u540C\uFF0C\u6CBB\u7597\u4E5F\u9700\u968F\u4E4B\u8C03\u6574\u3002',
          observations: [
            "\u6CE8\u610F\u89C2\u5BDF\u540C\u4E00\u75C7\u72B6\u5728\u4E0D\u540C\u4EBA\u8EAB\u4E0A\u7684\u4E0D\u540C\u8868\u73B0\uFF08\u5982\u540C\u6837\u662F\u5934\u75DB\uFF0C\u6709\u4EBA\u504F\u5934\u75DB\u5904\u53D1\u70ED\u3001\u6709\u4EBA\u89C9\u5F97\u53D1\u51C9\uFF09",
            '\u7559\u610F\u8EAB\u4F53"\u8C61"\u7684\u53D8\u5316\u89C4\u5F8B\u2014\u2014\u540C\u4E00\u4E2A\u4EBA\u7684\u820C\u82D4\u5728\u4E00\u5929\u5185\u4E5F\u4F1A\u53D8\u5316',
            "\u5B66\u4F1A\u533A\u5206\u4E3B\u89C2\u611F\u89C9\uFF08\u6015\u51B7\uFF09\u548C\u5BA2\u89C2\u5F81\u8C61\uFF08\u820C\u82D4\u767D\uFF09"
          ],
          commonMistakes: [
            "\u8BA4\u4E3A\u53D6\u8C61\u6BD4\u7C7B\u662F\u968F\u610F\u7684\u8054\u60F3\uFF0C\u6CA1\u6709\u89C4\u5F8B\u53EF\u5FAA",
            '\u53EA\u770B\u4E00\u4E2A"\u8C61"\u5C31\u4E0B\u7ED3\u8BBA\uFF0C\u5FFD\u89C6\u591A\u8C61\u5408\u53C2',
            "\u628A\u4E2D\u533B\u7684\u601D\u7EF4\u65B9\u5F0F\u548C\u897F\u533B\u7684\u68C0\u67E5\u5BF9\u7ACB\u8D77\u6765"
          ],
          misconceptions: [
            "\u53D6\u8C61\u6BD4\u7C7B=\u80E1\u4E71\u8054\u60F3\u2014\u2014\u5B9E\u9645\u4E0A\u5B83\u6709\u4E25\u683C\u7684\u7C7B\u6BD4\u89C4\u5219\u548C\u4E34\u5E8A\u9A8C\u8BC1",
            '\u4E2D\u533B\u53EA\u9760"\u770B"\u2014\u2014\u5176\u5B9E\u4E2D\u533B\u7684"\u56DB\u8BCA\u5408\u53C2"\u662F\u7EFC\u5408\u591A\u7EF4\u5EA6\u4FE1\u606F\u540E\u5224\u65AD',
            "\u53E4\u4EBA\u7684\u89C2\u5BDF\u4E0D\u9760\u8C31\u2014\u2014\u8BB8\u591A\u4E2D\u533B\u89C2\u5BDF\u5728\u5F53\u4EE3\u7814\u7A76\u4E2D\u5DF2\u88AB\u521D\u6B65\u9A8C\u8BC1\uFF08\u5982\u820C\u82D4\u4E0E\u6D88\u5316\u529F\u80FD\u7684\u5173\u8054\uFF09"
          ],
