          parentNodeId: null,
          childrenIds: [],
          coreConcept: "\u5BD2\u70ED\u89C2\u5BDF\u662F\u7CFB\u7EDF\u6027\u5730\u6536\u96C6\u8EAB\u4F53\u7684\u6E29\u5EA6\u76F8\u5173\u4FE1\u606F\uFF0C\u5305\u62EC\u4E3B\u89C2\u611F\u89C9\uFF08\u6015\u51B7/\u6015\u70ED\uFF09\u548C\u5BA2\u89C2\u4F53\u5F81\uFF08\u4F53\u6E29/\u89E6\u611F\uFF09\u4E24\u4E2A\u5C42\u9762\u3002",
          whyItMatters: "\u5BD2\u70ED\u662F\u4E2D\u533B\u516B\u7EB2\u8FA8\u8BC1\u7684\u7075\u9B42\u4E4B\u4E00\u3002\u5B66\u4F1A\u7CFB\u7EDF\u89C2\u5BDF\u5BD2\u70ED\u7EBF\u7D22\uFF0C\u662F\u8FDB\u5165\u8FA8\u8BC1\u601D\u7EF4\u7684\u7B2C\u4E00\u6B65\u3002",
          beginnerExplanation: '\u5BD2\u70ED\u89C2\u5BDF\u5C31\u662F\u4F60"\u6536\u96C6\u8EAB\u4F53\u6E29\u5EA6\u4FE1\u606F"\u7684\u8FC7\u7A0B\u3002\u4F60\u53EF\u4EE5\u95EE\u81EA\u5DF1\u51E0\u4E2A\u95EE\u9898\uFF1A\u2460\u8FD9\u4E2A\u4EBA\u81EA\u5DF1\u89C9\u5F97\u51B7\u8FD8\u662F\u70ED\uFF1F\uFF08\u4E3B\u89C2\u611F\u89C9\uFF09\u2461\u6211\u6478\u4ED6\u76AE\u80A4\u611F\u89C9\u600E\u6837\uFF1F\uFF08\u89E6\u611F\uFF09\u2462\u4F53\u6E29\u8BA1\u663E\u793A\u591A\u5C11\u5EA6\uFF1F\uFF08\u5BA2\u89C2\u6570\u636E\uFF09\u2463\u51B7\u548C\u70ED\u5728\u54EA\u4E2A\u90E8\u4F4D\u6700\u660E\u663E\uFF1F\u2464\u4EC0\u4E48\u60C5\u51B5\u4E0B\u4F1A\u52A0\u91CD\u6216\u7F13\u89E3\uFF1F\u8FD9\u4E94\u4E2A\u95EE\u9898\u5C31\u662F\u4F60\u7684"\u6E29\u5EA6\u6536\u96C6\u6E05\u5355"\u3002\u4E0D\u95EE\u51FA\u8FD9\u4E9B\uFF0C\u5C31\u4E0D\u8981\u6025\u7740\u8BF4"\u5BD2\u8BC1"\u8FD8\u662F"\u70ED\u8BC1"\u3002',
          deeperExplanation: "\u5BD2\u70ED\u7684\u89C2\u5BDF\u5728\u300A\u4F24\u5BD2\u8BBA\u300B\u4E2D\u88AB\u5206\u4E3A\u591A\u4E2A\u5C42\u6B21\uFF1A\u6076\u5BD2\uFF08\u6DFB\u8863\u52A0\u88AB\u4ECD\u89C9\u51B7\uFF09\u3001\u754F\u5BD2\uFF08\u5F97\u6696\u5219\u51CF\uFF09\u3001\u53D1\u70ED\uFF08\u4F53\u6E29\u5347\u9AD8\uFF09\u3001\u6F6E\u70ED\uFF08\u5B9A\u65F6\u53D1\u70ED\uFF09\u3001\u5BD2\u70ED\u5F80\u6765\uFF08\u4E00\u9635\u51B7\u4E00\u9635\u70ED\uFF09\u3001\u624B\u8DB3\u53A5\u51B7\uFF08\u56DB\u80A2\u53D1\u51C9\u4F46\u4E0D\u4E00\u5B9A\u6015\u51B7\uFF09\u7B49\u3002\u6BCF\u79CD\u5BD2\u70ED\u6A21\u5F0F\u5BF9\u5E94\u4E0D\u540C\u7684\u75C5\u673A\u548C\u6CBB\u6CD5\u3002\u516D\u7ECF\u8FA8\u8BC1\u4E2D\uFF0C\u5BD2\u70ED\u662F\u5224\u65AD\u75C5\u5728\u4E09\u9633\u8FD8\u662F\u4E09\u9634\u7684\u5173\u952E\u3002\u5728\u672C\u5883\u4E2D\uFF0C\u6211\u4EEC\u53EA\u8981\u6C42\u51C6\u786E\u89C2\u5BDF\u548C\u8BB0\u5F55\uFF0C\u4E0D\u8981\u6C42\u8FA8\u8BC1\u3002",
          observations: [
            "\u4E3B\u89C2\u611F\u53D7\uFF1A\u662F\u6015\u51B7\u8FD8\u662F\u6015\u70ED\uFF1F\u8FD8\u662F\u51B7\u4E00\u9635\u70ED\u4E00\u9635\uFF1F",
            "\u89E6\u611F\uFF1A\u76AE\u80A4\uFF08\u989D\u5934\u3001\u624B\u3001\u811A\u3001\u8179\u90E8\uFF09\u7684\u6E29\u5EA6\u548C\u53D8\u5316",
            "\u4F53\u6E29\u8BA1\u8BFB\u6570\uFF08\u5982\u6709\u6D4B\u91CF\uFF09",
            "\u51B7\u70ED\u611F\u4E0E\u996E\u98DF\u7684\u5173\u7CFB\u2014\u2014\u60F3\u559D\u70ED\u6C34\u8FD8\u662F\u60F3\u559D\u51B7\u6C34",
            "\u51B7\u70ED\u611F\u4E0E\u7A7F\u8863\u591A\u5C11\u3001\u73AF\u5883\u6E29\u5EA6\u7684\u5173\u7CFB"
          ],
          commonMistakes: [
            '\u628A"\u624B\u811A\u51C9"\u7B49\u540C\u4E8E"\u5BD2\u8BC1"\u2014\u2014\u624B\u811A\u51C9\u53EF\u80FD\u53EA\u662F\u672B\u68A2\u5FAA\u73AF\u95EE\u9898',
            '\u628A"\u53D1\u70E7"\u7B49\u540C\u4E8E"\u70ED\u8BC1"\u2014\u2014\u53D1\u70E7\u662F\u4F53\u6E29\u5347\u9AD8\uFF0C\u4E2D\u533B\u53EF\u80FD\u8FA8\u4E3A\u8868\u8BC1\u3001\u70ED\u8BC1\u6216\u5BD2\u70ED\u9519\u6742',
            "\u5FFD\u89C6\u6E29\u5EA6\u53D8\u5316\u7684\u65F6\u95F4\u89C4\u5F8B\u2014\u2014\u5BD2\u70ED\u51FA\u73B0\u7684\u65F6\u6BB5\uFF08\u5348\u540E\u3001\u591C\u95F4\u3001\u6E05\u6668\uFF09\u6709\u91CD\u8981\u9274\u522B\u610F\u4E49"
          ],
          misconceptions: [
            '\u4F53\u6E29\u6B63\u5E38\u5C31\u6CA1\u6709\u5BD2\u70ED\u95EE\u9898\u2014\u2014\u5F88\u591A\u4E2D\u533B\u7684"\u5BD2\u8BC1"\u60A3\u8005\u4F53\u6E29\u5B8C\u5168\u6B63\u5E38',
            "\u6015\u51B7\u5C31\u662F\u9633\u865A\u2014\u2014\u6015\u51B7\u53EF\u80FD\u662F\u9633\u865A\u3001\u4E5F\u53EF\u80FD\u662F\u8868\u5BD2\u8BC1\u3001\u8FD8\u53EF\u80FD\u662F\u70ED\u53A5",
            '\u591A\u559D\u70ED\u6C34\u5BF9\u6240\u6709\u7684"\u51B7"\u90FD\u597D\u2014\u2014\u771F\u5B9E\u7684\u5BD2\u70ED\u6BD4"\u51B7=\u70ED\u6C34"\u590D\u6742\u5F97\u591A'
          ],
          classicReferences: ["classic-suwen-yinyang", "classic-shanghan"],
