          coreConcept: "\u820C\u8C61\u89C2\u5BDF\u5206\u4E3A\u820C\u8D28\uFF08\u989C\u8272\u3001\u5F62\u6001\uFF09\u548C\u820C\u82D4\uFF08\u989C\u8272\u3001\u539A\u8584\u3001\u6DA6\u71E5\uFF09\u4E24\u4E2A\u7EF4\u5EA6\uFF0C\u662F\u8EAB\u4F53\u5185\u90E8\u72B6\u6001\u7684\u76F4\u89C2\u53CD\u6620\u3002",
          whyItMatters: '\u820C\u8BCA\u662F\u4E2D\u533B\u8BCA\u65AD\u4E2D\u6700\u76F4\u89C2\u3001\u6700\u6709\u7279\u8272\u7684\u65B9\u6CD5\u4E4B\u4E00\u3002\u5B66\u4F1A\u89C2\u5BDF\u820C\u8C61\u7B49\u4E8E\u5B66\u4F1A\u4E86\u76F4\u63A5"\u770B"\u8EAB\u4F53\u5185\u90E8\u7684\u72B6\u51B5\u3002',
          beginnerExplanation: '\u820C\u8C61\u89C2\u5BDF\u53EF\u4EE5\u7B80\u5355\u5206\u4E3A\u4E24\u6B65\uFF1A\u7B2C\u4E00\u6B65\u770B"\u820C\u5934\u672C\u8EAB"\uFF08\u820C\u8D28\uFF09\u2014\u2014\u989C\u8272\u662F\u6DE1\u7EA2\u3001\u504F\u7EA2\u3001\u8FD8\u662F\u504F\u767D\uFF1F\u820C\u4F53\u662F\u6B63\u5E38\u5927\u5C0F\u3001\u80D6\u5927\u3001\u8FD8\u662F\u7626\u5C0F\uFF1F\u6709\u6CA1\u6709\u9F7F\u75D5\u3001\u88C2\u7EB9\u3001\u7600\u70B9\uFF1F\u7B2C\u4E8C\u6B65\u770B"\u820C\u5934\u4E0A\u7684\u8986\u76D6\u7269"\uFF08\u820C\u82D4\uFF09\u2014\u2014\u6709\u6CA1\u6709\u82D4\uFF1F\u82D4\u662F\u767D\u662F\u9EC4\uFF1F\u662F\u8584\u662F\u539A\uFF1F\u662F\u6E7F\u6DA6\u8FD8\u662F\u5E72\u71E5\uFF1F\u80FD\u4E0D\u80FD\u522E\u6389\uFF1F\u628A\u8FD9\u4E24\u6B65\u5206\u522B\u8BB0\u5F55\u6E05\u695A\uFF0C\u5C31\u662F\u4E00\u4EFD\u5B8C\u6574\u7684\u820C\u8C61\u89C2\u5BDF\u62A5\u544A\u3002\u6CE8\u610F\u770B\u820C\u5934\u8981\u5728\u81EA\u7136\u5149\u4E0B\u770B\uFF0C\u521A\u5403\u5B8C\u4E1C\u897F\u6216\u8005\u5237\u5B8C\u7259\u4F1A\u5F71\u54CD\u5224\u65AD\u3002',
          deeperExplanation: '\u820C\u8BCA\u5728\u4E34\u5E8A\u4E2D\u6709\u7CFB\u7EDF\u7684\u5206\u7C7B\u4F53\u7CFB\u3002\u820C\u8D28\u65B9\u9762\uFF1A\u7EA2\u820C\uFF08\u70ED\u8BC1\uFF09\u3001\u7EDB\u820C\uFF08\u70ED\u5165\u8425\u8840\uFF09\u3001\u6DE1\u767D\u820C\uFF08\u865A\u5BD2/\u6C14\u8840\u4E24\u865A\uFF09\u3001\u7D2B\u820C\uFF08\u7600\u8840/\u70ED\u6BD2\uFF09\u3001\u9752\u820C\uFF08\u5BD2\u51DD/\u7600\u8840\uFF09\u7B49\u3002\u820C\u5F62\u65B9\u9762\uFF1A\u8001\u5AE9\uFF08\u8001\u820C\u5C5E\u5B9E\u3001\u5AE9\u820C\u5C5E\u865A\uFF09\u3001\u80D6\u7626\uFF08\u80D6\u5927\u5C5E\u6E7F\u3001\u7626\u8584\u5C5E\u9634\u865A\uFF09\u3001\u9F7F\u75D5\uFF08\u813E\u865A\u6E7F\u76DB\uFF09\u3001\u88C2\u7EB9\uFF08\u9634\u4F24/\u8840\u865A\uFF09\u3001\u8292\u523A\uFF08\u70ED\u76DB\uFF09\u3002\u820C\u82D4\u65B9\u9762\uFF1A\u767D\u82D4\uFF08\u8868\u8BC1/\u5BD2\u8BC1\uFF09\u3001\u9EC4\u82D4\uFF08\u70ED\u8BC1\uFF09\u3001\u7070\u9ED1\u82D4\uFF08\u5BD2\u6781\u6216\u70ED\u6781\uFF09\u3001\u539A\u8584\uFF08\u90AA\u6C14\u6DF1\u6D45\uFF09\u3001\u6DA6\u71E5\uFF08\u6D25\u6DB2\u76C8\u4E8F\uFF09\u3001\u817B\u8150\uFF08\u6E7F\u6D4A/\u98DF\u79EF\uFF09\u3001\u5265\u843D\uFF08\u80C3\u6C14\u9634\u4E24\u4F24\uFF09\u3002\u820C\u4E0B\u7EDC\u8109\u65B9\u9762\uFF1A\u9752\u7D2B\u66F2\u5F20\u63D0\u793A\u7600\u8840\u3002\u6BCF\u4E00\u7C7B\u820C\u8C61\u90FD\u6709\u5BF9\u5E94\u7684\u4E34\u5E8A\u610F\u4E49\uFF0C\u4F46\u521D\u5B66\u8005\u4E00\u5B9A\u8981\u5148\u5B66\u4F1A"\u770B"\u548C"\u8BB0\u5F55"\uFF0C\u518D\u53BB\u5B66\u4E60"\u89E3\u8BFB"\u3002',
          observations: [
            "\u820C\u8D28\u989C\u8272\u2014\u2014\u6DE1\u7EA2\u3001\u504F\u7EA2\u3001\u504F\u6DE1\u3001\u7D2B\u6697\u8FD8\u662F\u9752\u7D2B",
            "\u820C\u4F53\u5F62\u6001\u2014\u2014\u5927\u5C0F\u662F\u5426\u9002\u4E2D\u3001\u6709\u65E0\u9F7F\u75D5\u3001\u88C2\u7EB9\u3001\u7600\u70B9",
            "\u820C\u82D4\u6709\u65E0\u2014\u2014\u6709\u82D4\u8FD8\u662F\u65E0\u82D4\uFF08\u955C\u9762\u820C\uFF09",
            "\u820C\u82D4\u989C\u8272\u548C\u539A\u8584\u2014\u2014\u767D/\u9EC4/\u7070\u9ED1\u3001\u8584/\u539A",
            "\u820C\u82D4\u7684\u6DA6\u71E5\u2014\u2014\u6E7F\u6DA6\u3001\u5E72\u71E5\u3001\u8FD8\u662F\u6ED1\u817B"
          ],
          commonMistakes: [
            "\u53EA\u5173\u6CE8\u820C\u82D4\u4E0D\u5173\u6CE8\u820C\u8D28\u2014\u2014\u820C\u8D28\u53CD\u6620\u6C14\u8840\u7684\u6839\u672C\u72B6\u6001\uFF0C\u6BD4\u820C\u82D4\u66F4\u57FA\u7840",
            "\u770B\u5B8C\u820C\u8C61\u5C31\u7ACB\u523B\u4E0B\u8BCA\u65AD\u2014\u2014\u820C\u8C61\u53EA\u662F\u7EBF\u7D22\u4E4B\u4E00\uFF0C\u56DB\u8BCA\u5408\u53C2\u624D\u80FD\u4E0B\u7ED3\u8BBA",
            "\u5FFD\u89C6\u996E\u98DF\u5BF9\u820C\u8C61\u7684\u5F71\u54CD\u2014\u2014\u5496\u5561\u3001\u725B\u5976\u3001\u6709\u8272\u98DF\u7269\u90FD\u4F1A\u6539\u53D8\u820C\u82D4\u5916\u89C2"
          ],
          misconceptions: [
            "\u820C\u82D4\u8D8A\u539A\u75C5\u8D8A\u91CD\u2014\u2014\u820C\u82D4\u539A\u4E0D\u4E00\u5B9A\u4EE3\u8868\u75C5\u91CD\uFF0C\u53EF\u80FD\u662F\u98DF\u79EF\u6216\u6E7F\u6D4A\uFF0C\u5177\u4F53\u8981\u770B\u4F34\u968F\u75C7\u72B6",
            "\u820C\u8C61\u53EF\u4EE5\u5355\u72EC\u786E\u8BCA\u2014\u2014\u820C\u8C61\u53EA\u662F\u56DB\u8BCA\u4E4B\u4E00\uFF0C\u4E0D\u80FD\u66FF\u4EE3\u5176\u4ED6\u8BCA\u65AD\u65B9\u6CD5",
            "\u6BCF\u4E2A\u4EBA\u90FD\u5E94\u8BE5\u5728\u65E9\u4E0A\u770B\u820C\u8C61\u2014\u2014\u5237\u7259\u524D\u770B\u820C\u8C61\u6700\u63A5\u8FD1\u771F\u5B9E\u7684\u820C\u8C61\u72B6\u6001"
          ],
          classicReferences: ["classic-shetai"],
          formulaReferences: [],
          paradoxIds: [],
          masteryRequirements: ["case-obs-tongue-01", "case-obs-tongue-02", "case-obs-tongue-03"]
