          coreConcept: "\u865A\u5B9E\u5224\u65AD\u4E2D\u5B58\u5728\u5047\u8C61\uFF1A\u5927\u5B9E\u6709\u7FB8\u72B6\uFF08\u5B9E\u90AA\u63A9\u76D6\u6B63\u865A\uFF09\uFF0C\u81F3\u865A\u6709\u76DB\u5019\uFF08\u865A\u6781\u51FA\u73B0\u5B9E\u8C61\uFF09\u3002\u7A7F\u900F\u5047\u8C61\u9760\u820C\u8109\u548C\u6574\u4F53\u72B6\u6001\u3002",
          whyItMatters: '\u88AB\u5047\u8C61\u8FF7\u60D1\u4F1A\u5BFC\u81F4"\u865A\u8BC1\u8BEF\u653B\u3001\u5B9E\u8BC1\u8BEF\u8865"\u2014\u2014\u865A\u5B9E\u641E\u53CD\u662F\u6240\u6709\u8FA8\u8BC1\u9519\u8BEF\u4E2D\u540E\u679C\u6700\u4E25\u91CD\u7684\u4E00\u7C7B\u3002',
          beginnerExplanation: '\u6709\u4EBA\u770B\u8D77\u6765\u5F88\u5F31\uFF08\u7626\u3001\u6CA1\u529B\u6C14\uFF09\uFF0C\u4F46\u809A\u5B50\u80C0\u9F13\u9F13\u7684\u3001\u6309\u7740\u4E0D\u8212\u670D\u2014\u2014\u8FD9\u4E0D\u662F\u7EAF\u7CB9\u7684"\u865A"\uFF0C\u4E5F\u4E0D\u662F\u7EAF\u7CB9\u7684"\u5B9E"\uFF0C\u800C\u662F"\u813E\u865A+\u6C14\u6EDE"\u4E24\u4E2A\u95EE\u9898\u540C\u65F6\u5B58\u5728\u3002\u4E0D\u80FD\u53EA\u770B\u5230"\u865A"\u5C31\u8865\u3001\u4E5F\u4E0D\u80FD\u53EA\u770B"\u8179\u80C0"\u5C31\u653B\u3002',
          deeperExplanation: '\u865A\u5B9E\u771F\u5047\u7684\u9274\u522B\u8981\u70B9\uFF1A\u2460\u820C\u8C61\u662F"\u6700\u4E0D\u9A97\u4EBA"\u7684\u8BC1\u636E\u2014\u2014\u820C\u6DE1\u80D6\u5AE9\u3001\u82D4\u8584\u6DA6\u4E3A\u865A\uFF1B\u820C\u7EA2\u7EDB\u3001\u82D4\u539A\u817B\u71E5\u4E3A\u5B9E\u3002\u2461\u8109\u8C61\u2014\u2014\u6709\u529B\u4E3A\u5B9E\u3001\u65E0\u529B\u4E3A\u865A\uFF0C\u8FD9\u662F"\u8109\u8C61\u5B9A\u5F8B"\u3002\u2462\u75C5\u53F2\u548C\u75C5\u7A0B\u2014\u2014\u4E45\u75C5\u591A\u865A\u3001\u66B4\u75C5\u591A\u5B9E\u3002\u2463\u5BF9\u6CBB\u7597\u7684\u53CD\u5E94\u2014\u2014"\u8865\u4E4B\u65E0\u6548\u6216\u53CD\u589E"\u63D0\u793A\u53EF\u80FD\u4E0D\u662F\u7EAF\u865A\uFF0C"\u653B\u4E4B\u65E0\u76CA\u6216\u66F4\u865A"\u63D0\u793A\u53EF\u80FD\u4E0D\u662F\u7EAF\u5B9E\u3002\u4E34\u5E8A\u5E38\u89C1\u865A\u5B9E\u771F\u5047\u60C5\u5F62\uFF1A\u813E\u865A\u4E0D\u8FD0\u2192\u6C14\u6EDE\u8179\u80C0\uFF08\u81F3\u865A\u6709\u76DB\u5019\uFF09\uFF1B\u75F0\u6E7F\u5185\u76DB\u2192\u80A2\u4F53\u56F0\u91CD\u4F3C\u865A\uFF08\u5927\u5B9E\u6709\u7FB8\u72B6\uFF09\u3002',
          observations: [
            '\u820C\u8C61\u662F"\u91D1\u6807\u51C6"\u2014\u2014\u820C\u6DE1\u80D6\u5AE9\u4E3A\u865A\u3001\u820C\u7EA2\u7EDB\u5E72\u4E3A\u5B9E',
            "\u8109\u8C61\u6709\u529B\u65E0\u529B\u2014\u2014\u6709\u529B\u4E3A\u5B9E\u3001\u65E0\u529B\u4E3A\u865A",
            "\u8179\u80C0\u7684\u6027\u8D28\u2014\u2014\u65F6\u80C0\u65F6\u51CF\u3001\u5F97\u6309\u5219\u8212\u4E3A\u865A\uFF1B\u6301\u7EED\u80C0\u6EE1\u3001\u62D2\u6309\u4E3A\u5B9E",
            "\u9762\u8272\u2014\u2014\u840E\u9EC4\u65E0\u534E\u4E3A\u865A\u3001\u7EA2\u8D64\u6CB9\u5149\u4E3A\u5B9E",
            '\u4F53\u578B\u7684"\u5B9E\u611F"\u2014\u2014\u808C\u8089\u7ED3\u5B9E\u4E3A\u5B9E\u3001\u808C\u8089\u677E\u8F6F\u4E3A\u865A'
          ],
          commonMistakes: [
            "\u770B\u5230\u8179\u80C0\u5C31\u5224\u65AD\u4E3A\u5B9E\u8BC1\uFF0C\u5FFD\u7565\u4F34\u968F\u7684\u865A\u8C61",
            "\u770B\u5230\u6D88\u7626\u5C31\u5224\u65AD\u4E3A\u865A\u8BC1\uFF0C\u5FFD\u7565\u53EF\u80FD\u5B58\u5728\u7684\u5B9E\u90AA\uFF08\u5982\u866B\u79EF\u3001\u75F0\u6E7F\uFF09",
            "\u4E0D\u91CD\u89C6\u820C\u8109\u5728\u865A\u5B9E\u5224\u65AD\u4E2D\u7684\u6838\u5FC3\u5730\u4F4D"
          ],
          misconceptions: [
            "\u4EBA\u7626\u5C31\u4E00\u5B9A\u662F\u865A \u2014\u2014 \u7626\u4EBA\u4E5F\u53EF\u4EE5\u6709\u5B9E\u8BC1\uFF08\u5982\u809D\u706B\u3001\u75F0\u70ED\uFF09",
            "\u8179\u80C0\u5C31\u4E00\u5B9A\u662F\u6709\u4E1C\u897F\u5835\u7740 \u2014\u2014 \u813E\u865A\u6C14\u6EDE\u4E5F\u4F1A\u80C0\uFF0C\u6027\u8D28\u4E0D\u540C\u4E8E\u98DF\u79EF\u7684\u80C0"
          ],
