          coreConcept: "\u9634\u9633\u662F\u516B\u7EB2\u7684\u603B\u7EB2\uFF0C\u628A\u8868\u91CC\u3001\u5BD2\u70ED\u3001\u865A\u5B9E\u6574\u5408\u4E3A\u9634\u8BC1/\u9633\u8BC1\u4E24\u5927\u65B9\u5411\uFF0C\u628A\u63E1\u75BE\u75C5\u6574\u4F53\u6027\u8D28\u3002",
          whyItMatters: '\u6CA1\u6709\u9634\u9633\u603B\u7EB2\u7684\u89C6\u89D2\uFF0C\u5C31\u4F1A\u9677\u5165"\u516D\u4E2A\u7EF4\u5EA6\u5404\u81EA\u72EC\u7ACB"\u7684\u788E\u7247\u5316\u601D\u7EF4\uFF0C\u770B\u4E0D\u5230\u75BE\u75C5\u7684\u6574\u4F53\u8D8B\u52BF\u3002',
          beginnerExplanation: '\u516B\u7EB2\u6709\u516D\u5BF9\u5177\u4F53\u7EB2\u9886\uFF08\u8868\u91CC\u3001\u5BD2\u70ED\u3001\u865A\u5B9E\uFF09\uFF0C\u518D\u52A0\u4E0A\u4E00\u5BF9"\u603B\u7EB2"\uFF08\u9634\u9633\uFF09\u3002\u6BD4\u5982\uFF1A\u8868\u3001\u70ED\u3001\u5B9E\u90FD\u5C5E\u4E8E"\u9633"\u7684\u8303\u7574\uFF0C\u91CC\u3001\u5BD2\u3001\u865A\u90FD\u5C5E\u4E8E"\u9634"\u7684\u8303\u7574\u3002\u628A\u516D\u4E2A\u7EF4\u5EA6\u7684\u4FE1\u606F"\u52A0\u603B"\u4E00\u4E0B\uFF0C\u5C31\u80FD\u5F97\u5230\u6574\u4F53\u65B9\u5411\u2014\u2014\u504F\u9633\u8FD8\u662F\u504F\u9634\u3002',
          deeperExplanation: '\u5F20\u4ECB\u5BBE\u5728\u300A\u666F\u5CB3\u5168\u4E66\u300B\u4E2D\u8BBA\uFF1A"\u9634\u9633\u4E3A\u7EB2\uFF0C\u516D\u53D8\u4E3A\u76EE\u3002" \u516B\u7EB2\u8FA8\u8BC1\u7684\u5C42\u6B21\u7ED3\u6784\u662F\uFF1A\u7B2C\u4E00\u5C42\uFF08\u6700\u9876\u5C42\uFF09\u2192\u9634\u9633\uFF0C\u7B2C\u4E8C\u5C42\u2192\u8868\u91CC\uFF08\u75C5\u4F4D\uFF09\u3001\u5BD2\u70ED\uFF08\u75C5\u6027\uFF09\u3001\u865A\u5B9E\uFF08\u90AA\u6B63\uFF09\u3002\u9634\u9633\u4E0D\u662F\u7B2C\u516D\u5BF9\u8FA8\u8BC1\u7EB2\u9886\uFF0C\u800C\u662F\u524D\u4E09\u4E2A\u7EB2\u9886\u7684"\u7EFC\u5408\u7EF4\u5EA6"\u3002\u5728\u5177\u4F53\u5E94\u7528\u4E2D\uFF1A\u2460\u6309\u516B\u7EB2\u9010\u9879\u5206\u6790\uFF08\u5148\u8FA8\u8868\u91CC\u3001\u518D\u8FA8\u5BD2\u70ED\u3001\u518D\u8FA8\u865A\u5B9E\uFF09\uFF1B\u2461\u6309\u9634\u9633\u6574\u5408\uFF08\u8BA1\u7B97\u5404\u7EF4\u5EA6\u7684\u65B9\u5411\u603B\u548C\uFF09\uFF1B\u2462\u5F62\u6210\u603B\u4F53\u7684"\u9634\u8BC1/\u9633\u8BC1"\u5224\u65AD\uFF0C\u8FDB\u800C\u6307\u5BFC\u6CBB\u7597\u5927\u539F\u5219\u3002',
          observations: [
            "\u5148\u9010\u9879\u5206\u6790\u516B\u7EB2\u4E2D\u6BCF\u4E00\u5BF9\u7684\u65B9\u5411",
            '\u518D"\u52A0\u603B"\u5404\u7EF4\u5EA6\u7684\u65B9\u5411\u2014\u2014\u5927\u90E8\u5206\u7EF4\u5EA6\u540C\u5411\u65F6\uFF0C\u603B\u7EB2\u5224\u65AD\u5C31\u6E05\u6670',
            '\u770B"\u603B\u4F53\u8D8B\u52BF"\uFF1A\u673A\u4F53\u662F\u504F\u4EA2\u594B\uFF08\u9633\uFF09\u8FD8\u662F\u504F\u8870\u9000\uFF08\u9634\uFF09',
            '\u770B"\u6CBB\u7597\u65B9\u5411"\uFF1A\u603B\u7EB2\u4E3A\u9633\u2192\u6E05\u6563\u653B\uFF1B\u603B\u7EB2\u4E3A\u9634\u2192\u6E29\u8865\u56FA'
          ],
          commonMistakes: [
            '\u628A\u9634\u9633\u603B\u7EB2\u5F53\u4F5C"\u7B2C\u516D\u5BF9\u7EB2\u9886"\u800C\u4E0D\u662F"\u524D\u4E09\u4E2A\u7684\u6574\u5408"',
            "\u8BA4\u4E3A\u4E00\u4E2A\u75C5\u4F8B\u8981\u4E48\u7EAF\u9634\u8981\u4E48\u7EAF\u9633\u2014\u2014\u5B9E\u9645\u4E0A\u5F88\u591A\u75C5\u4F8B\u662F\u9634\u9633\u9519\u6742\u7684",
            "\u53EA\u505A\u4E86\u9634\u9633\u603B\u7EB2\u5224\u65AD\u5C31\u505C\u6B62\uFF0C\u4E0D\u518D\u5206\u6790\u5177\u4F53\u7684\u8868\u91CC\u5BD2\u70ED\u865A\u5B9E"
          ],
          misconceptions: [
            "\u9634\u9633\u5C31\u662F\u5BD2\u70ED\u2014\u2014\u4E0D\u5BF9\uFF0C\u9634\u9633\u7684\u8303\u56F4\u6BD4\u5BD2\u70ED\u5927\u5F97\u591A",
            "\u9633\u8BC1\u5C31\u662F\u597D\u3001\u9634\u8BC1\u5C31\u662F\u574F\u2014\u2014\u4E0D\u5BF9\uFF0C\u53EA\u662F\u4E0D\u540C\u7684\u72B6\u6001\uFF0C\u5404\u6709\u5404\u7684\u6CBB\u6CD5"
          ],
