          whyItMatters: '\u8840\u865A\u548C\u6C14\u865A\u90FD\u53EF\u8868\u73B0\u4E3A"\u82CD\u767D"\uFF0C\u4F46\u8840\u865A\u8865\u8840\u3001\u6C14\u865A\u8865\u6C14\uFF0C\u65B9\u5411\u4E0D\u540C\u3002\u9274\u522B\u70B9\u4E0D\u5728"\u82CD\u767D"\u800C\u5728\u4F34\u968F\u7EBF\u7D22\u3002',
          beginnerExplanation: '\u8840\u5C31\u50CF\u662F\u8EAB\u4F53\u7684"\u8425\u517B\u8F93\u9001\u7CFB\u7EDF"\u3002\u8840\u865A\u65F6\uFF0C\u5404\u4E2A\u90E8\u4F4D\u5F97\u4E0D\u5230\u8DB3\u591F\u7684\u8425\u517B\uFF1A\u5927\u8111\u7F3A\u8840\u4F1A\u5934\u6655\uFF0C\u5FC3\u810F\u7F3A\u8840\u4F1A\u5FC3\u60B8\uFF0C\u76AE\u80A4\u7F3A\u8840\u4F1A\u82CD\u767D\uFF0C\u6708\u7ECF\u7F3A\u8840\u4F1A\u91CF\u5C11\u3002"\u591A\u4E2A\u90E8\u4F4D\u540C\u65F6\u7F3A\u8425\u517B"\u662F\u8840\u865A\u7684\u5178\u578B\u6A21\u5F0F\u3002',
          deeperExplanation: '\u8840\u7684\u751F\u6210\uFF1A\u813E\u80C3\u8FD0\u5316\u6C34\u8C37\u7CBE\u5FAE\u2192\u4E0A\u8F93\u4E8E\u5FC3\u80BA\u2192\u5949\u5FC3\u5316\u8D64\u4E3A\u8840\u3002\u540C\u65F6\u80BE\u85CF\u7CBE\u3001\u7CBE\u5316\u8840\u3002\u6545\u8840\u865A\u4E0E\u813E\uFF08\u751F\u5316\u4E4B\u6E90\uFF09\u3001\u80BE\uFF08\u7CBE\u8840\u4E92\u5316\uFF09\u3001\u5FC3\uFF08\u5316\u8D64\u529F\u80FD\uFF09\u5173\u7CFB\u5BC6\u5207\u3002\u8840\u7684\u751F\u7406\u529F\u80FD\uFF1A\u2460\u6FE1\u517B\u5168\u8EAB\uFF08\u810F\u8151\u7ECF\u7EDC\u3001\u56DB\u80A2\u767E\u9AB8\uFF09\uFF1B\u2461\u5316\u795E\uFF08\u8840\u6DB2\u662F\u795E\u5FD7\u6D3B\u52A8\u7684\u7269\u8D28\u57FA\u7840\uFF0C\u6240\u8C13"\u8840\u8005\uFF0C\u795E\u6C14\u4E5F"\uFF09\u3002\u8840\u865A\u65F6\uFF0C\u6FE1\u517B\u529F\u80FD\u4E0B\u964D\u8868\u73B0\u4E3A\u9762\u8272\u65E0\u534E\u3001\u5934\u6655\u773C\u82B1\u3001\u722A\u7532\u8106\u8584\u3001\u80A2\u4F53\u9EBB\u6728\uFF1B\u5316\u795E\u4E0D\u8DB3\u5219\u5FC3\u60B8\u5931\u7720\u3001\u591A\u68A6\u5065\u5FD8\u3002',
          observations: [
            "\u9762\u8272\u662F\u6DE1\u767D\u8FD8\u662F\u82CD\u767D\u8FD8\u662F\u840E\u9EC4\uFF08\u4E0D\u540C\u8840\u865A\u7A0B\u5EA6\u7684\u8272\u8C03\u53D8\u5316\uFF09",
            "\u662F\u5426\u6709\u5934\u6655\u773C\u82B1\uFF0C\u5C24\u5176\u662F\u8D77\u7ACB\u65F6\u52A0\u91CD\uFF08\u8840\u4E0D\u517B\u8111\uFF09",
            "\u662F\u5426\u6709\u5FC3\u60B8\u3001\u5931\u7720\u3001\u591A\u68A6\uFF08\u8840\u4E0D\u517B\u5FC3\uFF09",
            "\u6307\u7532\u662F\u5426\u82CD\u767D\u3001\u8106\u8584\u3001\u6613\u65AD\uFF08\u8840\u4E0D\u517B\u7B4B\uFF09",
            "\u5973\u6027\u6708\u7ECF\u91CF\u662F\u5426\u504F\u5C11\u3001\u8272\u6DE1\u3001\u5EF6\u671F\uFF08\u8840\u4E0D\u5145\u80DE\u5BAB\uFF09"
          ],
          commonMistakes: [
            "\u770B\u5230\u9762\u8272\u82CD\u767D\u5C31\u76F4\u63A5\u5224\u65AD\u4E3A\u8840\u865A\u2014\u2014\u6C14\u865A\u3001\u5BD2\u51DD\u4E5F\u53EF\u81F4\u9762\u8272\u82CD\u767D",
            "\u628A\u5934\u6655\u90FD\u5F53\u8840\u865A\u2014\u2014\u809D\u9633\u4E0A\u4EA2\u3001\u75F0\u6E7F\u4E2D\u963B\u4E5F\u53EF\u81F4\u5934\u6655",
            '\u8840\u865A\u548C\u9634\u865A\u6DF7\u6DC6\u2014\u2014\u8840\u865A\u504F"\u8272\u6DE1\u5931\u517B"\uFF0C\u9634\u865A\u504F"\u865A\u70ED\u5185\u6270"'
          ],
          misconceptions: [
            "\u8840\u865A\u5C31\u662F\u8D2B\u8840\u2014\u2014\u4E2D\u533B\u8840\u865A\u8303\u56F4\u6BD4\u8D2B\u8840\u5E7F\uFF0C\u6709\u4E9B\u8840\u5E38\u89C4\u6B63\u5E38\u7684\u60A3\u8005\u4E5F\u53EF\u6709\u8840\u865A\u8868\u73B0",
            "\u5403\u7EA2\u67A3\u5C31\u80FD\u8865\u8840\u2014\u2014\u4E2D\u533B\u8865\u8840\u5E38\u9700\u5065\u813E+\u8865\u80BE+\u8865\u6C14\u7EC4\u5408\uFF0C\u5355\u5473\u7EA2\u67A3\u4F5C\u7528\u6709\u9650",
            "\u8840\u8D8A\u8865\u8D8A\u597D\u2014\u2014\u8840\u865A\u517C\u6709\u6E7F\u3001\u7600\u65F6\uFF0C\u7EAF\u8865\u8840\u53CD\u800C\u52A9\u6E7F\u751F\u7600"
          ],
