          parentNodeId: null,
          childrenIds: ["v3-s4-n7"],
          coreConcept: "\u8840\u7684\u5BD2\u70ED\u9274\u522B\uFF1A\u8840\u5BD2\u5219\u51DD\u6EDE\u51B7\u75DB\u8272\u6697\uFF0C\u8840\u70ED\u5219\u5984\u884C\u63D0\u524D\u8272\u7EA2\u3002\u540C\u4E00\u7CFB\u7EDF\u7684\u76F8\u53CD\u65B9\u5411\u3002",
          whyItMatters: "\u8840\u5BD2\u7528\u6E29\u7ECF\u3001\u8840\u70ED\u7528\u51C9\u8840\uFF0C\u65B9\u5411\u5B8C\u5168\u76F8\u53CD\u3002\u6708\u7ECF\u95EE\u9898\u662F\u4E34\u5E8A\u5E38\u89C1\u573A\u666F\uFF0C\u5BD2\u70ED\u8BEF\u5224\u5219\u6CBB\u7597\u5357\u8F95\u5317\u8F99\u3002",
          beginnerExplanation: '\u8840\u4E5F\u5206\u5BD2\u70ED\uFF1A\u8840\u5BD2\u5C31\u50CF\u51AC\u5929\u6C34\u7BA1\u91CC\u7684\u6C34\u2014\u2014\u51BB\u4F4F\u4E86\uFF0C\u6C34\u6D41\u6162\uFF0C\u989C\u8272\u6697\uFF0C\u8FD8\u75BC\uFF1B\u8840\u70ED\u5C31\u50CF\u590F\u5929\u6C34\u7BA1\u91CC\u7684\u6C34\u2014\u2014\u6C34\u6E29\u9AD8\uFF0C\u6D41\u5F97\u5FEB\uFF0C\u989C\u8272\u7EA2\uFF0C\u8FD8\u53EF\u80FD"\u6EA2\u51FA\u6765"\u3002\u540C\u6837\u662F\u6708\u7ECF\u95EE\u9898\uFF0C\u5148\u770B"\u5BD2\u8FD8\u662F\u70ED"\u518D\u51B3\u5B9A\u600E\u4E48\u5904\u7406\u3002',
          deeperExplanation: "\u8840\u5BD2\u7684\u6210\u56E0\uFF1A\u5916\u5BD2\uFF08\u7ECF\u671F\u611F\u5BD2\uFF09+\u5185\u5BD2\uFF08\u9633\u865A\u4F53\u8D28\uFF09\u3002\u75C5\u673A\uFF1A\u5BD2\u5BA2\u8840\u8109\u2192\u6536\u5F15\u51DD\u6EDE\u2192\u8840\u884C\u4E0D\u7545\u2192\u4E0D\u901A\u5219\u75DB\u3002\u4F34\u968F\u7EBF\u7D22\uFF1A\u9762\u8272\u9752\u6697\u3001\u754F\u5BD2\u80A2\u51B7\u3001\u5F97\u6E29\u5219\u51CF\u3001\u820C\u6DE1\u7D2B\u82D4\u767D\u6ED1\u3001\u8109\u6C89\u8FDF\u5F26\u7D27\u3002\u8840\u70ED\u7684\u6210\u56E0\uFF1A\u5916\u611F\u70ED\u90AA+\u60C5\u5FD7\u5316\u706B+\u9634\u865A\u751F\u70ED\u3002\u75C5\u673A\uFF1A\u70ED\u5165\u8840\u5206\u2192\u8840\u884C\u52A0\u901F\u2192\u8FEB\u8840\u5984\u884C\u3002\u4F34\u968F\u7EBF\u7D22\uFF1A\u9762\u7EA2\u76EE\u8D64\u3001\u5FC3\u70E6\u53E3\u6E34\u3001\u820C\u7EA2\u7EDB\u3001\u8109\u6ED1\u6570\u3002\u6CE8\u610F\u8840\u70ED\u4E0E\u8840\u7600\u53EF\u517C\u89C1\uFF08\u70ED\u707C\u8840\u6210\u7600\uFF09\uFF0C\u8840\u5BD2\u4E0E\u8840\u7600\u4EA6\u5E38\u540C\u65F6\u51FA\u73B0\uFF08\u5BD2\u51DD\u8840\u7600\uFF09\u3002",
          observations: [
            "\u6708\u7ECF\u5468\u671F\u662F\u63D0\u524D\u8FD8\u662F\u63A8\u540E\uFF08\u8840\u70ED\u63D0\u524D\u3001\u8840\u5BD2\u63A8\u540E\uFF09",
            "\u7ECF\u8840\u989C\u8272\u662F\u6DF1\u7EA2\u8FD8\u662F\u6697\u7D2B\uFF08\u8840\u70ED\u8272\u7EA2\u3001\u8840\u5BD2\u8272\u6697\uFF09",
            "\u7ECF\u8D28\u662F\u7A20\u8FD8\u662F\u7A00\u3001\u6709\u65E0\u8840\u5757\uFF08\u8840\u70ED\u8D28\u7A20\u3001\u5BD2\u51DD\u8840\u7600\u6709\u5757\uFF09",
            "\u5C0F\u8179\u662F\u51B7\u75DB\u8FD8\u662F\u707C\u75DB\uFF08\u8840\u5BD2\u51B7\u75DB\u3001\u8840\u70ED\u53EF\u80C0\u75DB\u6216\u707C\u75DB\uFF09",
            "\u5168\u8EAB\u4F34\u968F\u7EBF\u7D22\uFF1A\u754F\u5BD2\u80A2\u51B7\uFF08\u8840\u5BD2\uFF09\u8FD8\u662F\u5FC3\u70E6\u53E3\u6E34\uFF08\u8840\u70ED\uFF09"
          ],
          commonMistakes: [
            "\u770B\u5230\u6708\u7ECF\u6709\u8840\u5757\u5C31\u5224\u65AD\u4E3A\u8840\u7600\u2014\u2014\u5BD2\u51DD\u4E5F\u53EF\u81F4\u8840\u5757\uFF0C\u4E14\u8840\u7600\u6709\u5757\u504F\u6697\u3001\u8840\u70ED\u6709\u5757\u504F\u7EA2",
            "\u628A\u6240\u6709\u6708\u7ECF\u63D0\u524D\u5F53\u8840\u70ED\u2014\u2014\u6C14\u865A\u4E0D\u6444\u4E5F\u53EF\u81F4\u6708\u7ECF\u63D0\u524D\uFF08\u63D0\u524D\u4F46\u8272\u6DE1\u91CF\u591A\uFF09",
            "\u628A\u75DB\u7ECF\u4E00\u5F8B\u5F53\u5BD2\u8BC1\u2014\u2014\u6E7F\u70ED\u8574\u7ED3\u4E5F\u53EF\u81F4\u75DB\u7ECF\uFF08\u4F46\u75DB\u4E3A\u707C\u75DB\u3001\u5E26\u4E0B\u9EC4\u7A20\uFF09"
          ],
          misconceptions: [
            "\u5973\u6027\u90FD\u662F\u5BD2\u6027\u4F53\u8D28\u2014\u2014\u5973\u6027\u6709\u5BD2\u6709\u70ED\uFF0C\u4E0D\u80FD\u4E00\u6982\u800C\u8BBA",
            '\u7ECF\u671F\u4E0D\u80FD\u5403\u51C9\u7684\u662F\u56E0\u4E3A\u4F1A"\u5BD2"\u2014\u2014\u786E\u5B9E\u53EF\u80FD\u81F4\u5BD2\u51DD\u8840\u7600\uFF0C\u4F46\u4F53\u8D28\u504F\u70ED\u8005\u5C11\u91CF\u51C9\u6027\u98DF\u7269\u65E0\u59A8'
          ],
