          coreConcept: "\u6C14\u8840\u6D25\u6DB2\u4E09\u8005\u540C\u6E90\u4E92\u5316\u3001\u540C\u75C5\u76F8\u7275\u2014\u2014\u770B\u5230\u4E00\u4E2A\u95EE\u9898\u8981\u60F3\u5230\u5B83\u53EF\u80FD\u7275\u8FDE\u53E6\u5916\u4E24\u4E2A\u3002",
          whyItMatters: "\u4E34\u5E8A\u5E38\u89C1\u6C14\u8840\u6D25\u6DB2\u540C\u75C5\u2014\u2014\u6C14\u865A\u8840\u7600\u3001\u6C14\u6EDE\u8840\u7600\u3001\u6C14\u8840\u4E24\u865A\u3001\u6D25\u4E8F\u8840\u71E5\u3002\u53EA\u6CBB\u4E00\u4E2A\u5F80\u5F80\u4E0D\u591F\u3002",
          beginnerExplanation: '\u6C14\u3001\u8840\u3001\u6D25\u6DB2\u662F"\u94C1\u4E09\u89D2"\uFF1A\u6C14\u662F\u52A8\u529B\uFF08\u5FEB\u9012\u5458\uFF09\uFF0C\u8840\u662F\u8425\u517B\uFF08\u5305\u88F9\uFF09\uFF0C\u6D25\u6DB2\u662F\u6C34\u5206\uFF08\u4FDD\u6E7F\u6C34\uFF09\u3002\u4E09\u8005\u4E92\u76F8\u5F71\u54CD\uFF1A\u6C14\u4E0D\u591F\u2192\u8840\u63A8\u4E0D\u52A8\uFF08\u6C14\u865A\u8840\u7600\uFF09\uFF1B\u8840\u4E0D\u591F\u2192\u6C14\u6CA1\u5730\u65B9\u4F4F\uFF08\u8840\u865A\u6C14\u4EA6\u865A\uFF09\uFF1B\u8840\u548C\u6D25\u6DB2\u66F4\u662F\u4E00\u5BB6\u2014\u2014\u5931\u8840\u540E\u4F1A\u53E3\u6E34\uFF0C\u5927\u6C57\u540E\u4E5F\u4F1A\u53E3\u6E34\u3002',
          deeperExplanation: "\u4E09\u5927\u5173\u7CFB\u8BE6\u89E3\uFF1A\u2460\u6C14\u4E0E\u8840\u2014\u2014\u6C14\u4E3A\u8840\u4E4B\u5E05\uFF08\u751F\u8840\uFF1A\u8425\u6C14+\u6D25\u6DB2\u2192\u8840\uFF1B\u884C\u8840\uFF1A\u6C14\u63A8\u8840\u884C\uFF1B\u6444\u8840\uFF1A\u6C14\u56FA\u6444\u8840\u6DB2\u4E0D\u5916\u6EA2\uFF09\uFF0C\u8840\u4E3A\u6C14\u4E4B\u6BCD\uFF08\u8840\u8F7D\u6C14\u4EE5\u884C\uFF0C\u8840\u517B\u6C14\u4EE5\u5145\uFF09\u3002\u6C14\u865A\u53EF\u81F4\u8840\u865A\uFF08\u65E0\u529B\u751F\u8840\uFF09\u3001\u8840\u7600\uFF08\u65E0\u529B\u884C\u8840\uFF09\u3001\u51FA\u8840\uFF08\u65E0\u529B\u6444\u8840\uFF09\u3002\u2461\u6C14\u4E0E\u6D25\u6DB2\u2014\u2014\u6C14\u80FD\u751F\u6D25\uFF08\u813E\u80C3\u4E4B\u6C14\u8FD0\u5316\u6C34\u8C37\u6210\u6D25\u6DB2\uFF09\u3001\u884C\u6D25\uFF08\u6C14\u63A8\u52A8\u6D25\u6DB2\u8F93\u5E03\uFF09\u3001\u6444\u6D25\uFF08\u6C14\u56FA\u6444\u6D25\u6DB2\u4E0D\u6D41\u5931\uFF09\u3002\u2462\u8840\u4E0E\u6D25\u6DB2\u2014\u2014\u540C\u6E90\u4E92\u5316\uFF0C\u540C\u4E3A\u6DB2\u6001\uFF0C\u540C\u6765\u6E90\u4E8E\u6C34\u8C37\u7CBE\u5FAE\u3002\u5927\u6C57\u3001\u5927\u5410\u3001\u5927\u6CFB\u3001\u5927\u5931\u8840\u540E\uFF0C\u6D25\u4E0E\u8840\u4E92\u76F8\u8865\u5145\u3002",
          observations: [
            "\u8840\u865A\u60A3\u8005\u662F\u5426\u4F34\u6709\u53E3\u5E72\u3001\u4FBF\u5E72\uFF08\u63D0\u793A\u6D25\u8840\u540C\u4E8F\uFF09",
            "\u6C14\u865A\u60A3\u8005\u662F\u5426\u4F34\u6709\u53E3\u5E72\uFF08\u6C14\u865A\u4E0D\u80FD\u884C\u6D25\u2192\u6D25\u6DB2\u4E0A\u4E0D\u6765\uFF09",
            "\u5931\u8840\u60A3\u8005\u662F\u5426\u51FA\u73B0\u53E3\u6E34\uFF08\u8840\u4E8F\u2192\u6D25\u6DB2\u4EE3\u507F\u2192\u6D25\u4EA6\u4E8F\uFF09",
            "\u5927\u6C57\u540E\u662F\u5426\u51FA\u73B0\u5FC3\u614C\uFF08\u6C57\u4E3A\u5FC3\u4E4B\u6DB2\u2192\u6C57\u591A\u4F24\u53CA\u5FC3\u4E4B\u6C14\u8840\uFF09",
            '\u662F\u5426\u51FA\u73B0"\u6C14\u865A+\u8840\u7600"\u6216"\u8840\u865A+\u6D25\u4E8F"\u7684\u590D\u5408\u8868\u73B0'
          ],
          commonMistakes: [
            "\u53EA\u5173\u6CE8\u4E00\u79CD\u7269\u8D28\u2014\u2014\u770B\u5230\u8840\u865A\u53EA\u8865\u8840\uFF0C\u5FFD\u7565\u53EF\u80FD\u540C\u65F6\u5B58\u5728\u7684\u6C14\u865A\u6216\u6D25\u4E8F",
            '\u628A"\u6C14\u80FD\u6444\u8840"\u7406\u89E3\u6210"\u6C14\u628A\u8840\u6293\u4F4F"\u2014\u2014\u5176\u5B9E\u662F\u6C14\u7684\u56FA\u6444\u529F\u80FD\u9632\u6B62\u8840\u6DB2\u5984\u884C',
            '\u5FFD\u89C6"\u6C57\u8840\u540C\u6E90"\u7684\u4E34\u5E8A\u610F\u4E49\u2014\u2014\u5927\u6C57\u540E\u4E0D\u4EC5\u4F24\u6D25\uFF0C\u4E5F\u4F24\u8840\u4F24\u5FC3'
          ],
          misconceptions: [
            "\u6C14\u8840\u6D25\u6DB2\u662F\u4E09\u79CD\u72EC\u7ACB\u7684\u4E1C\u897F\u2014\u2014\u5B83\u4EEC\u662F\u540C\u4E00\u4E2A\u6765\u6E90\u7684\u4E09\u79CD\u4E0D\u540C\u529F\u80FD\u5F62\u6001",
            "\u6C14\u8D8A\u591A\u8D8A\u597D\u2014\u2014\u6C14\u6709\u4F59\u4FBF\u662F\u706B",
            "\u8865\u8840\u5C31\u662F\u8865\u6D25\u6DB2\u2014\u2014\u4E0D\u540C\uFF0C\u8840\u8981\u8865\u8840\u3001\u6D25\u4E8F\u8981\u751F\u6D25"
          ],
