          coreConcept: '\u80BE\u85CF\u7CBE\u3001\u4E3B\u6C34\u3001\u4E3B\u7EB3\u6C14\u3002\u80BE\u865A\u7684\u6807\u5FD7\u6027\u7EBF\u7D22"\u8170\u819D\u9178\u8F6F+\u9AD3/\u9AA8/\u751F\u6B96/\u6C34\u6DB2"\u3002\u80BE\u865A\u5206\u9634\u865A\uFF08\u70ED\uFF09\u3001\u9633\u865A\uFF08\u5BD2\uFF09\u3001\u7CBE\u4E8F\uFF08\u65E9\u8870\uFF09\u3002',
          whyItMatters: "\u80BE\u4E3A\u5148\u5929\u4E4B\u672C\u2014\u2014\u80BE\u865A\u95EE\u9898\u662F\u5F88\u591A\u6162\u6027\u75C5\u7684\u6839\u57FA\u3002\u8865\u80BE\u8981\u5206\u9634\u9633\uFF0C\u58EE\u9633\u2260\u8865\u80BE\u3002",
          beginnerExplanation: '\u4E2D\u533B\u7684"\u80BE"\u662F\u8EAB\u4F53\u6700\u6DF1\u5C42\u6B21\u7684"\u80FD\u91CF\u50A8\u5907\u7CFB\u7EDF"\uFF1A\u7BA1\u751F\u957F\uFF08\u4ECE\u5C0F\u5230\u5927\u7684\u53D1\u80B2\uFF09\u3001\u7BA1\u751F\u6B96\uFF08\u751F\u80B2\u80FD\u529B\uFF09\u3001\u7BA1\u6C34\u6DB2\uFF08\u5C0F\u4FBF\u7684\u5F00\u5173\uFF09\u3001\u7BA1\u7EB3\u6C14\uFF08\u6DF1\u547C\u5438\u7684\u80FD\u529B\uFF09\u3002\u80BE\u865A\u7684\u5178\u578B\u8868\u73B0\uFF1A\u8170\u819D\u9178\u8F6F+\uFF08\u5934\u6655\u8033\u9E23/\u591C\u5C3F\u591A/\u8BB0\u5FC6\u529B\u5DEE/\u6027\u529F\u80FD\u4E0B\u964D\uFF09\u3002\u80BE\u865A\u5206\u9634\u9633\uFF1A\u6015\u51B7\u662F\u9633\u865A\u3001\u624B\u5FC3\u811A\u5FC3\u70ED\u662F\u9634\u865A\u3002',
          deeperExplanation: "\u80BE\u7684\u751F\u7406\u7279\u6027\uFF1A\u80BE\u4E3A\u5148\u5929\u4E4B\u672C\uFF08\u7980\u53D7\u4E8E\u7236\u6BCD\u4E4B\u7CBE\uFF09\u3001\u80BE\u4E3B\u5C01\u85CF\uFF08\u85CF\u7CBE\u800C\u4E0D\u6CC4\uFF09\u3001\u6C34\u706B\u4E4B\u810F\uFF08\u5185\u5BD3\u5143\u9634\u5143\u9633\uFF09\u3002\u80BE\u4E0E\u5404\u810F\u8151\u5173\u7CFB\uFF1A\u80BE\u4E0E\u8180\u80F1\u76F8\u8868\u91CC\uFF08\u5171\u53F8\u6C34\u6DB2\u4EE3\u8C22\uFF09\u3001\u5FC3\u80BE\u76F8\u4EA4\uFF08\u80BE\u6C34\u4E0A\u6D4E\u5FC3\u706B\u4E0D\u4EA2\uFF09\u3001\u809D\u80BE\u540C\u6E90\uFF08\u7CBE\u8840\u4E92\u5316\u3001\u4E59\u7678\u540C\u6E90\uFF09\u3001\u80BA\u80BE\u76F8\u751F\uFF08\u91D1\u6C34\u76F8\u751F\u3001\u547C\u5438\u4E4B\u6839\uFF09\u3001\u813E\u80BE\u76F8\u5173\uFF08\u5148\u5929\u751F\u540E\u5929\u3001\u540E\u5929\u517B\u5148\u5929\uFF09\u3002\u5E38\u89C1\u8BC1\u578B\uFF1A\u80BE\u9634\u865A\uFF08\u8170\u819D\u9178\u8F6F+\u4E94\u5FC3\u70E6\u70ED+\u76D7\u6C57\u68A6\u9057\uFF09\u3001\u80BE\u9633\u865A\uFF08\u8170\u819D\u9178\u8F6F+\u754F\u5BD2\u80A2\u51B7+\u9633\u75FF\u591C\u5C3F\uFF09\u3001\u80BE\u7CBE\u4E0D\u8DB3\uFF08\u5C0F\u513F\u53D1\u80B2\u8FDF\u7F13/\u6210\u4EBA\u65E9\u8870\uFF09\u3001\u80BE\u6C14\u4E0D\u56FA\uFF08\u5C3F\u9891\u9057\u5C3F\u6ED1\u7CBE\u65E9\u6CC4\uFF09\u3001\u80BE\u4E0D\u7EB3\u6C14\uFF08\u547C\u591A\u5438\u5C11+\u52A8\u5219\u5598\uFF09\u3002",
          observations: [
            "\u8170\u819D\u7684\u611F\u89C9\uFF1A\u9178\u8F6F\uFF08\u865A\uFF09vs\u75BC\u75DB\uFF08\u5B9E/\u5916\u4F24\uFF09vs\u51B7\u75DB\uFF08\u9633\u865A\uFF09",
            "\u6C34\u6DB2\u7EBF\u7D22\uFF1A\u591C\u5C3F\u591A\uFF08\u80BE\u6C14\u4E0D\u56FA\uFF09vs\u5C3F\u6E05\u957F\uFF08\u9633\u865A\uFF09vs\u5C3F\u5C11\uFF08\u80BE\u6C14\u865A/\u80BE\u8870\u7AED\uFF09",
            "\u751F\u6B96\u7EBF\u7D22\uFF1A\u9633\u75FF\u65E9\u6CC4\uFF08\u9633\u865A\uFF09vs\u68A6\u9057\uFF08\u9634\u865A\uFF09vs\u7CBE\u5C11\uFF08\u7CBE\u4E8F\uFF09",
            "\u751F\u957F/\u65E9\u8870\u7EBF\u7D22\uFF1A\u53D1\u80B2\u8FDF\u7F13\uFF08\u5C0F\u513F\uFF09vs\u53D1\u767D\u9F7F\u677E\uFF08\u6210\u4EBA\uFF09vs\u9AA8\u8D28\u758F\u677E\uFF08\u8001\u5E74\uFF09",
            "\u7CBE\u795E\u7EBF\u7D22\uFF1A\u5934\u6655\u8033\u9E23\uFF08\u9AD3\u6D77\u4E0D\u8DB3\uFF09vs\u5065\u5FD8\uFF08\u80BE\u7CBE\u4E0D\u5145\u8111\uFF09vs\u6050\uFF08\u6050\u4F24\u80BE\uFF09"
          ],
          commonMistakes: [
            "\u8170\u819D\u9178\u8F6F\u5C31\u8865\u80BE\u2014\u2014\u6E7F\u963B\u7B4B\u9AA8\u4E5F\u53EF\u81F4\u8170\u819D\u9178\u8F6F\uFF0C\u4F46\u4F34\u6C89\u91CD\u611F\u3001\u82D4\u817B",
            "\u8865\u80BE\u5C31\u662F\u58EE\u9633\u2014\u2014\u80BE\u9634\u4E0D\u8DB3\u4E5F\u8981\u8865\u80BE\uFF08\u6ECB\u8865\u80BE\u9634\uFF09\uFF0C\u58EE\u9633\u836F\u53EA\u5BF9\u80BE\u9633\u865A\u6709\u6548\uFF0C\u9634\u865A\u7528\u58EE\u9633\u836F\u53CD\u4F24\u9634",
            "\u628A\u6240\u6709\u6027\u529F\u80FD\u4E0B\u964D\u5F52\u80BE\u2014\u2014\u809D\u90C1\u3001\u6E7F\u70ED\u3001\u5FC3\u813E\u4E24\u865A\u4E5F\u53EF\u81F4\u6027\u529F\u80FD\u95EE\u9898"
          ],
          misconceptions: [
            "\u80BE\u865A\u5C31\u662F\u80BE\u4E0D\u597D\uFF08\u80BE\u75C5\uFF09\u2014\u2014\u4E2D\u533B\u80BE\u865A\u4E0D\u7B49\u4E8E\u897F\u533B\u80BE\u529F\u80FD\u4E0D\u5168",
            '\u4E2D\u5E74\u4EBA\u8981\u8865\u80BE\u2014\u2014\u662F\u5426\u9700\u8981\u8865\u80BE\u53D6\u51B3\u4E8E"\u6709\u6CA1\u6709\u80BE\u865A\u7684\u8868\u73B0"\u800C\u4E0D\u662F\u5E74\u9F84',
            "\u5403\u8170\u5B50\u8865\u8170\u5B50\u2014\u2014\u4E2D\u533B\u80BE\u662F\u529F\u80FD\u7CFB\u7EDF\uFF0C\u52A8\u7269\u7684\u8170\u5B50\uFF08\u80BE\u4E0A\u817A\uFF09\u9AD8\u80C6\u56FA\u9187\uFF0C\u4E0D\u5B9C\u8FC7\u91CF"
          ],
          classicReferences: ["classic-su-wen-xuan-ming-wu-qi"],
          formulaReferences: ["formula-liu-wei-di-huang-wan", "formula-jin-gui-shen-qi-wan"],
