          parentNodeId: null,
          childrenIds: ["v3-s5-n5"],
          coreConcept: "\u6C14\u673A\u662F\u4EBA\u4F53\u5185\u6C14\u7684\u8FD0\u52A8\u673A\u5236\uFF0C\u6C14\u7684\u6B63\u5E38\u8FD0\u884C\u662F\u810F\u8151\u529F\u80FD\u6D3B\u52A8\u7684\u57FA\u7840\u3002",
          whyItMatters: '\u5927\u91CF\u529F\u80FD\u6027\u75BE\u75C5\u7684\u6838\u5FC3\u75C5\u673A\u662F\u6C14\u673A\u5931\u5E38\u800C\u975E\u5668\u8D28\u6027\u635F\u4F24\u2014\u2014\u7406\u89E3\u6C14\u673A\u662F\u4E2D\u533B"\u6CBB\u529F\u80FD\u6027\u75C5"\u7684\u72EC\u7279\u4F18\u52BF\u3002',
          beginnerExplanation: '\u6C14\u673A\u5C31\u662F"\u6C14\u600E\u4E48\u5728\u8EAB\u4F53\u91CC\u6D41\u52A8"\u3002\u5982\u679C\u628A\u8EAB\u4F53\u60F3\u8C61\u6210\u4E00\u5EA7\u57CE\u5E02\uFF1A\u6C14\u5C31\u662F\u4EA4\u901A\u6D41\u91CF\uFF0C\u6C14\u673A\u5C31\u662F\u4EA4\u901A\u7CFB\u7EDF\u3002\u57CE\u5E02\u6B63\u5E38\u8FD0\u8F6C\u9700\u8981\u8F66\u6D41\u987A\u7545\uFF08\u6C14\u673A\u6B63\u5E38\uFF09\u3002\u5982\u679C\u67D0\u4E2A\u8DEF\u6BB5\u5835\u4E86\uFF08\u6C14\u6EDE\uFF09\uFF0C\u90A3\u4E2A\u533A\u57DF\u5C31\u51FA\u95EE\u9898\uFF1B\u5982\u679C\u8F66\u6D41\u9006\u884C\uFF08\u6C14\u9006\uFF09\uFF0C\u5C31\u4F1A\u9020\u6210\u4E8B\u6545\u3002\u4E2D\u533B\u8C03\u7406\u6C14\u673A\uFF0C\u5F88\u591A\u65F6\u5019\u5C31\u662F\u5728"\u758F\u5BFC\u4EA4\u901A"\u2014\u2014\u4E0D\u662F\u589E\u52A0\u8F66\u8F86\uFF08\u8865\u6C14\uFF09\uFF0C\u800C\u662F\u8BA9\u73B0\u6709\u7684\u8F66\u8F86\u987A\u7545\u8FD0\u884C\uFF08\u884C\u6C14\u3001\u7406\u6C14\uFF09\u3002',
          deeperExplanation: '\u6C14\u5728\u4EBA\u4F53\u5185\u7684\u8FD0\u52A8\u5F62\u5F0F\u5305\u62EC\u56DB\u79CD\u57FA\u672C\u65B9\u5F0F\u2014\u2014\u5347\uFF08\u5411\u4E0A\uFF09\u3001\u964D\uFF08\u5411\u4E0B\uFF09\u3001\u51FA\uFF08\u5411\u5916\uFF09\u3001\u5165\uFF08\u5411\u5185\uFF09\u3002\u4E94\u810F\u516D\u8151\u5404\u6709\u5176\u6C14\u673A\u7279\u70B9\uFF1A\u809D\u6C14\u4E3B\u5347\u53D1\uFF08\u6761\u8FBE\u8212\u7545\uFF09\uFF0C\u80BA\u6C14\u4E3B\u8083\u964D\uFF08\u6E05\u8083\u4E0B\u964D\uFF09\uFF0C\u813E\u6C14\u4E3B\u5347\u6E05\uFF08\u5C06\u7CBE\u5FAE\u7269\u8D28\u8F93\u9001\u5230\u5168\u8EAB\uFF09\uFF0C\u80C3\u6C14\u4E3B\u964D\u6D4A\uFF08\u5C06\u7CDF\u7C95\u5411\u4E0B\u4F20\u5BFC\uFF09\uFF0C\u5FC3\u6C14\u4E3B\u6563\uFF08\u6577\u5E03\u6C14\u8840\u5230\u5168\u8EAB\uFF09\uFF0C\u80BE\u6C14\u4E3B\u7EB3\uFF08\u6444\u7EB3\u80BA\u5438\u5165\u7684\u6E05\u6C14\uFF09\u3002\u6574\u4E2A\u6C14\u673A\u7CFB\u7EDF\u4EE5"\u5347\u964D\u51FA\u5165"\u4E3A\u57FA\u672C\u8FD0\u52A8\u5F62\u5F0F\uFF0C\u4EE5"\u809D\u4E3B\u758F\u6CC4"\u4E3A\u8C03\u7545\u4E2D\u67A2\u2014\u2014\u809D\u7684\u758F\u6CC4\u529F\u80FD\u6B63\u5E38\uFF0C\u5168\u8EAB\u6C14\u673A\u624D\u80FD\u8C03\u7545\u3002',
          observations: [
            "\u6CE8\u610F\u60C5\u7EEA\u53D8\u5316\u5BF9\u6C14\u673A\u7684\u5F71\u54CD\u2014\u2014\u751F\u6C14\u540E\u4E24\u80C1\u80C0\u75DB\uFF08\u809D\u6C14\u90C1\u7ED3\uFF09\u3001\u7D27\u5F20\u65F6\u80C3\u75DB\uFF08\u809D\u6C14\u72AF\u80C3\uFF09",
            "\u89C2\u5BDF\u6C14\u673A\u5931\u5E38\u7684\u65B9\u5411\u6027\u2014\u2014\u5411\u4E0A\u51B2\uFF08\u54B3\u5598\u3001\u55F3\u6C14\uFF09\u3001\u5411\u4E0B\u9677\uFF08\u8131\u809B\u3001\u5B50\u5BAB\u4E0B\u5782\uFF09\u3001\u5411\u5916\u6563\uFF08\u81EA\u6C57\u3001\u76D7\u6C57\uFF09",
            '\u7559\u610F"\u6C14\u7684\u90E8\u4F4D\u611F"\u2014\u2014\u75C5\u4EBA\u8BF4"\u6709\u4E1C\u897F\u5835\u5728\u80F8\u53E3""\u809A\u5B50\u80C0\u5F97\u50CF\u9F13\u4E00\u6837"\uFF0C\u591A\u662F\u6C14\u673A\u4E0D\u7545'
          ],
          commonMistakes: [
            '\u628A\u6240\u6709"\u6C14"\u7684\u95EE\u9898\u90FD\u5F53\u6210"\u6C14\u865A"\u6765\u5904\u7406\u2014\u2014\u5FFD\u7565\u4E86\u6C14\u6EDE\u3001\u6C14\u9006\u7B49\u6C14\u673A\u95EE\u9898',
            '\u8BA4\u4E3A\u6C14\u662F"\u7384\u5B66"\u6982\u5FF5\u2014\u2014\u6C14\u662F\u4E2D\u533B\u7684\u529F\u80FD\u6A21\u578B\uFF0C\u4E0D\u76F4\u63A5\u7B49\u540C\u4E8E\u7269\u7406\u5B66\u7684\u6C14\u4F53',
            "\u7528\u89E3\u5256\u5B66\u601D\u7EF4\u7406\u89E3\u6C14\u673A\u2014\u2014\u6C14\u673A\u63CF\u8FF0\u7684\u662F\u529F\u80FD\u5173\u7CFB\uFF0C\u4E0D\u662F\u6C14\u4F53\u5728\u7BA1\u9053\u4E2D\u6D41\u52A8"
          ],
          misconceptions: [
            '\u6C14\u662F\u4E2D\u533B\u865A\u6784\u7684\u6982\u5FF5\u2014\u2014\u73B0\u4EE3\u7814\u7A76\u5DF2\u521D\u6B65\u53D1\u73B0"\u6C14"\u4E0E\u751F\u7269\u7535\u3001\u80FD\u91CF\u4EE3\u8C22\u7B49\u751F\u7406\u73B0\u8C61\u76F8\u5173',
            "\u6C14\u673A\u7406\u8BBA\u592A\u62BD\u8C61\u3001\u4E34\u5E8A\u7528\u4E0D\u4E0A\u2014\u2014\u5B9E\u9645\u4E0A\u7406\u6C14\u6CD5\u662F\u4E34\u5E8A\u6700\u5E38\u7528\u7684\u6CBB\u6CD5\u4E4B\u4E00",
            '\u8865\u6C14\u5C31\u662F\u8BA9\u6C14\u53D8\u591A\u2014\u2014\u8865\u6C14\u548C\u884C\u6C14\u662F\u4E24\u56DE\u4E8B\uFF0C\u4E0D\u5206\u6E05\u695A\u4F1A\u72AF"\u8D8A\u8865\u8D8A\u5835"\u7684\u9519\u8BEF'
          ],
          classicReferences: [],
          formulaReferences: [],
