          whyItMatters: '\u810F\u8151\u662F\u75C5\u673A\u7684"\u843D\u5730"\u5355\u4F4D\u2014\u2014\u6C14\u673A\u3001\u6C14\u8840\u3001\u9634\u9633\u7684\u5931\u5E38\uFF0C\u6700\u7EC8\u90FD\u8981\u843D\u5230\u5177\u4F53\u810F\u8151\u624D\u80FD\u6307\u5BFC\u5206\u6790\u4E0E\u5B66\u4E60\u3002',
          beginnerExplanation: '\u4E2D\u533B\u7684\u4E94\u810F\u4E0D\u662F\u89E3\u5256\u56FE\u4E0A\u7684\u5668\u5B98\uFF0C\u800C\u662F\u4E94\u5957"\u529F\u80FD\u90E8\u95E8"\uFF1A\u809D\u8D1F\u8D23"\u758F\u901A\u8C03\u5EA6"\u3001\u5FC3\u8D1F\u8D23"\u8840\u8109\u4E0E\u795E\u5FD7"\u3001\u813E\u8D1F\u8D23"\u8FD0\u5316\u4F9B\u7ED9"\u3001\u80BA\u8D1F\u8D23"\u547C\u5438\u4E0E\u901A\u8C03\u6C34\u6DB2"\u3001\u80BE\u8D1F\u8D23"\u85CF\u7CBE\u4E0E\u4E3B\u6C34"\u3002\u810F\u8151\u75C5\u673A\u5C31\u662F\u95EE\uFF1A"\u8FD9\u4E2A\u90E8\u95E8\u672C\u6765\u8D1F\u8D23\u4EC0\u4E48\uFF1F\u5B83\u73B0\u5728\u54EA\u91CC\u5E72\u4E0D\u52A8\u4E86\uFF1F\u5E72\u4E0D\u52A8\u4E4B\u540E\u4F1A\u5192\u51FA\u54EA\u4E9B\u8868\u73B0\uFF1F"',
          deeperExplanation: '\u810F\u8151\u75C5\u673A\u7684\u63A8\u6F14\u9075\u5FAA"\u751F\u7406\u2192\u75C5\u7406\u2192\u8868\u73B0"\uFF1A\u4EE5\u809D\u4E3A\u4F8B\uFF0C\u751F\u7406\u4E0A\u809D\u4E3B\u758F\u6CC4\uFF08\u8C03\u7545\u6C14\u673A\u3001\u8C03\u7545\u60C5\u5FD7\u3001\u4FC3\u8FDB\u813E\u80C3\u8FD0\u5316\uFF09\u3001\u4E3B\u85CF\u8840\uFF1B\u758F\u6CC4\u5931\u5E38\u5219\u809D\u6C14\u90C1\u7ED3\uFF08\u6C14\u6EDE\uFF09\u3001\u90C1\u800C\u5316\u706B\uFF08\u809D\u706B\u4E0A\u708E\uFF09\u3001\u6A2A\u9006\u72AF\u813E\uFF08\u6728\u4E58\u571F\uFF09\u3001\u6216\u4E45\u90C1\u5316\u98CE\uFF08\u809D\u9633\u5316\u98CE\uFF09\u2014\u2014\u7531\u6B64\u5BF9\u5E94\u51FA\u80C1\u80C0\u3001\u70E6\u8E81\u3001\u80C3\u80C0\u3001\u7729\u6655\u7B49\u4E00\u7CFB\u5217\u8868\u73B0\u3002\u8FD9\u79CD"\u4ECE\u529F\u80FD\u5230\u5931\u5E38"\u7684\u63A8\u6F14\u65B9\u5F0F\uFF0C\u628A\u96F6\u6563\u75C7\u72B6\u7EC4\u7EC7\u6210\u6709\u56E0\u679C\u7684\u94FE\u6761\uFF0C\u662F\u8FA8\u8BC1\u63A8\u7406\u7684\u6838\u5FC3\u80FD\u529B\u3002',
          observations: [
            '\u5148\u660E\u786E"\u8FD9\u4E2A\u810F\u8151\u672C\u6765\u8D1F\u8D23\u4EC0\u4E48\u529F\u80FD"\uFF0C\u518D\u89C2\u5BDF"\u54EA\u9879\u529F\u80FD\u51FA\u4E86\u95EE\u9898"',
            "\u6CE8\u610F\u810F\u8151\u4E4B\u95F4\u7684\u5173\u8054\uFF1A\u809D\u75C5\u5E38\u72AF\u813E\u3001\u813E\u75C5\u5E38\u751F\u75F0\u3001\u80BA\u75C5\u5E38\u53CA\u80BE\uFF08\u6C34\u6DB2\uFF09",
            '\u533A\u5206"\u529F\u80FD\u5931\u5E38"\u4E0E"\u7269\u8D28\u4E8F\u865A"\uFF1A\u809D\u6C14\u90C1\u7ED3\u662F\u529F\u80FD\u5931\u8C03\uFF0C\u809D\u8840\u4E0D\u8DB3\u662F\u7269\u8D28\u532E\u4E4F\uFF0C\u4E8C\u8005\u53C8\u5E38\u76F8\u5173'
          ],
          commonMistakes: [
            '\u6309\u897F\u533B\u89E3\u5256\u4F4D\u7F6E\u7406\u89E3\u4E2D\u533B\u810F\u8151\uFF0C\u5FFD\u7565\u4E86\u4E2D\u533B\u810F\u8151\u662F"\u529F\u80FD\u7CFB\u7EDF"',
            '\u80CC"\u67D0\u810F\u5BF9\u5E94\u67D0\u75C7\u72B6"\u7684\u6E05\u5355\uFF0C\u9047\u5230\u53D8\u5F0F\u5C31\u5931\u624B',
            '\u5B64\u7ACB\u770B\u4E00\u4E2A\u810F\u8151\uFF0C\u5FFD\u7565"\u809D\u75C5\u53CA\u813E""\u80BA\u75C5\u53CA\u80BE"\u7B49\u810F\u8151\u95F4\u7684\u75C5\u673A\u8054\u52A8'
          ],
          misconceptions: [
            "\u4E2D\u533B\u7684\u5FC3\u809D\u813E\u80BA\u80BE\u5C31\u662F\u897F\u533B\u7684\u5BF9\u5E94\u5668\u5B98\u2014\u2014\u5B9E\u4E3A\u529F\u80FD\u7CFB\u7EDF\uFF0C\u4E0D\u53EF\u7B49\u540C",
            "\u810F\u8151\u75C5\u673A\u6709\u4E2A\u56FA\u5B9A\u75C7\u72B6\u6E05\u5355\u53EF\u80CC\u2014\u2014\u6B63\u786E\u505A\u6CD5\u662F\u4ECE\u529F\u80FD\u94FE\u6761\u63A8\u6F14",
            "\u4E00\u4E2A\u75C5\u53EA\u6D89\u53CA\u4E00\u4E2A\u810F\u8151\u2014\u2014\u4E34\u5E8A\u5E38\u89C1\u591A\u810F\u8151\u540C\u75C5\u6216\u76F8\u4E92\u7275\u8FDE"
          ],
          classicReferences: [],
