          parentNodeId: null,
          childrenIds: [],
          coreConcept: "\u53A5\u9634\u75C5\u662F\u5BD2\u70ED\u9519\u6742\u3001\u4E0A\u70ED\u4E0B\u5BD2\u7684\u590D\u6742\u8BC1\u5019\uFF0C\u6CBB\u7597\u8D35\u5728\u5BD2\u6E29\u5E76\u7528\u3001\u4EA4\u901A\u9634\u9633\u3002",
          whyItMatters: '\u53A5\u9634\u75C5\u4EE3\u8868\u4E86\u516D\u7ECF\u8FA8\u8BC1\u4E2D\u6700\u590D\u6742\u7684\u8BC1\u578B\u2014\u2014\u5B83\u6559\u4F1A\u4F60"\u5BD2\u70ED\u5E76\u7528"\u7684\u6CBB\u7597\u601D\u7EF4\uFF0C\u6253\u7834"\u5BD2\u8BC1\u53EA\u80FD\u7528\u70ED\u836F\u3001\u70ED\u8BC1\u53EA\u80FD\u7528\u5BD2\u836F"\u7684\u7B80\u5355\u4E8C\u5206\u6CD5\u3002',
          beginnerExplanation: '\u53A5\u9634\u75C5\u5C31\u50CF\u5929\u6C14"\u8BE5\u51B7\u4E0D\u51B7\u3001\u8BE5\u70ED\u4E0D\u70ED"\u7684\u53CD\u5E38\u2014\u2014\u4E0A\u9762\u706B\u5C71\u55B7\u53D1\uFF08\u6D88\u6E34\u3001\u5FC3\u4E2D\u70ED\uFF09\uFF0C\u4E0B\u9762\u51B0\u96EA\u8986\u76D6\uFF08\u4E0B\u5229\u3001\u624B\u8DB3\u51B7\uFF09\u3002\u8FD9\u79CD"\u4E24\u6781\u5206\u5316"\u4E0D\u662F\u7B80\u5355\u7684"\u5BD2\u6216\u70ED"\uFF0C\u800C\u662F\u51B7\u70ED\u540C\u65F6\u5B58\u5728\u3001\u4E92\u76F8\u5BF9\u6297\u3002\u5904\u7406\u8FD9\u79CD\u5C40\u9762\u4E0D\u80FD\u53EA\u7528"\u70ED\u6C34\u888B"\uFF08\u6E29\u836F\uFF09\u6216"\u51B0\u888B"\uFF08\u51C9\u836F\uFF09\uFF0C\u800C\u662F\u8981"\u4EA4\u901A\u4E0A\u4E0B"\u2014\u2014\u8BA9\u4E0A\u9762\u7684\u70ED\u964D\u4E0B\u6765\u6E29\u6696\u4E0B\u9762\uFF0C\u8BA9\u4E0B\u9762\u7684\u5BD2\u6162\u6162\u878D\u5316\u3002\u4E4C\u6885\u4E38\u5C31\u662F\u8FD9\u79CD"\u5BD2\u6E29\u5E76\u7528"\u7684\u4EE3\u8868\u65B9\u3002',
          deeperExplanation: '\u53A5\u9634\u662F\u516D\u7ECF\u7684\u6700\u540E\u4E00\u6761\uFF0C\u5728\u300A\u5468\u6613\u300B\u4E2D\u5BF9\u5E94"\u5265\u6781\u5FC5\u590D"\u7684\u8F6C\u6298\u70B9\u3002\u4ECE\u75C5\u673A\u4E0A\u7406\u89E3\uFF0C\u53A5\u9634\u75C5\u5177\u6709\u4EE5\u4E0B\u7279\u70B9\uFF1A(1) \u4ECE\u75C5\u4F4D\u4E0A\u2014\u2014\u6D89\u53CA\u809D\u4E0E\u5FC3\u5305\uFF0C\u809D\u4E3B\u758F\u6CC4\u3001\u5FC3\u5305\u4EE3\u5FC3\u53D7\u90AA\uFF0C\u53A5\u9634\u529F\u80FD\u5931\u5E38\u5219\u6C14\u673A\u9006\u4E71\uFF08\u6C14\u4E0A\u649E\u5FC3\uFF09\uFF1B(2) \u4ECE\u75C5\u6027\u4E0A\u2014\u2014\u5BD2\u70ED\u9519\u6742\uFF0C\u4E0D\u662F\u4EA4\u66FF\u51FA\u73B0\uFF08\u5982\u5C11\u9633\u7684\u5BD2\u70ED\u5F80\u6765\uFF09\uFF0C\u800C\u662F\u540C\u65F6\u5B58\u5728\u4E8E\u4E0D\u540C\u90E8\u4F4D\uFF08\u4E0A\u70ED\u4E0B\u5BD2\uFF09\uFF1B(3) \u4ECE\u9884\u540E\u4E0A\u2014\u2014\u53A5\u9634\u75C5"\u9634\u9633\u6D88\u957F"\u53D8\u5316\u6700\u4E3A\u5267\u70C8\uFF0C\u9633\u6C14\u6062\u590D\u5219\u751F\uFF08\u53A5\u540E\u53D1\u70ED\uFF09\uFF0C\u9633\u6C14\u4E0D\u8FD4\u5219\u4EA1\uFF08\u53A5\u4E0D\u56DE\uFF09\u3002\u5F20\u4EF2\u666F\u5728\u53A5\u9634\u75C5\u7BC7\u7528\u5927\u91CF\u7BC7\u5E45\u8BA8\u8BBA"\u53A5"\uFF08\u624B\u8DB3\u51B7\uFF09\u4E0E"\u70ED"\u7684\u5173\u7CFB\u2014\u2014"\u53A5"\uFF08\u9634\uFF09\u548C"\u70ED"\uFF08\u9633\uFF09\u7684\u6D88\u957F\u53D8\u5316\u662F\u5224\u65AD\u53A5\u9634\u75C5\u9884\u540E\u7684\u6838\u5FC3\u6307\u6807\u3002\u73B0\u4EE3\u7814\u7A76\u63D0\u793A\u4E4C\u6885\u4E38\u5177\u6709\u8C03\u8282\u514D\u75AB\u529F\u80FD\u3001\u6539\u5584\u80A0\u9053\u83CC\u7FA4\u3001\u6297\u708E\u7B49\u591A\u91CD\u4F5C\u7528\u3002',
          observations: [
            '\u6CE8\u610F"\u4E0A\u70ED"\u548C"\u4E0B\u5BD2"\u540C\u65F6\u5B58\u5728\u7684\u7279\u6B8A\u6027\u2014\u2014\u4E0A\u534A\u8EAB\u6709\u70ED\u8C61\u3001\u4E0B\u534A\u8EAB\u6709\u5BD2\u8C61',
            '\u89C2\u5BDF"\u9965\u800C\u4E0D\u6B32\u98DF"\u8FD9\u4E2A\u77DB\u76FE\u8868\u73B0\u2014\u2014\u80C3\u4E2D\u6709\u70ED\u5219\u9965\uFF0C\u813E\u4E2D\u6709\u5BD2\u5219\u4E0D\u80FD\u98DF',
            '\u7559\u610F"\u53A5"\u4E0E"\u70ED"\u7684\u6D88\u957F\u5173\u7CFB\u2014\u2014\u53A5\u51B7\u65F6\u95F4\u957F\u8FD8\u662F\u53D1\u70ED\u65F6\u95F4\u957F\uFF0C\u51B3\u5B9A\u9884\u540E'
          ],
          commonMistakes: [
            '\u628A\u53A5\u9634\u75C5\u7684"\u4E0A\u70ED\u4E0B\u5BD2"\u7B80\u5355\u7406\u89E3\u4E3A"\u4E0A\u706B+\u4F53\u5BD2"\u2014\u2014\u8FD9\u662F\u4E24\u4E2A\u5C42\u6B21\u7684\u95EE\u9898',
            '\u770B\u5230"\u6D88\u6E34"\u5C31\u8BA4\u4E3A\u662F\u7CD6\u5C3F\u75C5\u2014\u2014\u53E4\u4EE3"\u6D88\u6E34"\u6CDB\u6307\u53E3\u6E34\u591A\u996E\uFF0C\u4E0D\u7B49\u4E8E\u7CD6\u5C3F\u75C5',
            "\u8BEF\u7528\u653B\u4E0B\u2014\u2014\u53A5\u9634\u75C5\u8BEF\u4E0B\u4F1A\u4F7F\u4E0A\u70ED\u672A\u53BB\u800C\u4E0B\u5BD2\u66F4\u91CD"
          ],
          misconceptions: [
            "\u4E4C\u6885\u4E38\u53EA\u662F\u9A71\u86D4\u866B\u7684\u836F\u2014\u2014\u4E4C\u6885\u4E38\u7684\u6838\u5FC3\u529F\u6548\u662F\u5BD2\u6E29\u5E76\u7528\u3001\u8C03\u7406\u53A5\u9634\uFF0C\u4E0D\u9650\u4E8E\u9A71\u86D4",
            '\u53A5\u9634\u75C5\u7684"\u53A5"\u5C31\u662F\u624B\u8DB3\u51B7\u2014\u2014\u4F46\u53A5\u9634\u75C5\u7684\u624B\u8DB3\u51B7\u548C\u5176\u4ED6\u7ECF\u4E0D\u540C\uFF0C\u662F\u548C\u4E0A\u70ED\u540C\u65F6\u5B58\u5728\u7684',
            "\u53A5\u9634\u75C5\u5F88\u5C11\u89C1\u2014\u2014\u5BD2\u70ED\u9519\u6742\u7684\u8BC1\u5019\u5728\u6162\u6027\u80C3\u708E\u3001\u80A0\u6613\u6FC0\u7EFC\u5408\u5F81\u7B49\u75BE\u75C5\u4E2D\u5E76\u4E0D\u5C11\u89C1"
          ],
