          parentNodeId: null,
          childrenIds: ["v3-s7-n3"],
          coreConcept: "\u6807\u672C\u7F13\u6025\u662F\u6839\u636E\u75C5\u60C5\u7D27\u6025\u7A0B\u5EA6\u51B3\u5B9A\u6CBB\u7597\u4F18\u5148\u7EA7\u7684\u6CBB\u5219\u2014\u2014\u6025\u5219\u6CBB\u6807\u3001\u7F13\u5219\u6CBB\u672C\u3001\u6807\u672C\u4FF1\u6025\u5219\u6807\u672C\u540C\u6CBB\u3002",
          whyItMatters: '\u6CBB\u7597\u51B3\u7B56\u7684\u672C\u8D28\u662F"\u4F18\u5148\u7EA7\u7BA1\u7406"\u3002\u6807\u672C\u7F13\u6025\u544A\u8BC9\u4F60\uFF1A\u5728\u6709\u9650\u7684\u533B\u7597\u8D44\u6E90\u548C\u65F6\u95F4\u7A97\u53E3\u5185\uFF0C\u5148\u505A\u4EC0\u4E48\u3001\u540E\u505A\u4EC0\u4E48\u3002\u6CA1\u6709\u8FD9\u4E2A\u51B3\u7B56\u6846\u67B6\uFF0C\u6240\u6709\u6CBB\u5219\u5C31\u4F1A\u53D8\u6210"\u7406\u8BBA\u6B63\u786E\u4F46\u5B9E\u9645\u65E0\u6CD5\u64CD\u4F5C"\u7684\u7A7A\u8C08\u3002',
          beginnerExplanation: '\u60F3\u8C61\u4E00\u4E2A\u623F\u5B50\uFF1A\u5730\u57FA\u51FA\u4E86\u95EE\u9898\uFF08\u672C\u2014\u2014\u75C5\u6839\uFF09\uFF0C\u5899\u58C1\u51FA\u73B0\u4E86\u88C2\u7F1D\uFF08\u6807\u2014\u2014\u75C7\u72B6\uFF09\u3002\u7406\u60F3\u60C5\u51B5\u662F\u628A\u6574\u4E2A\u623F\u5B50\u7FFB\u65B0\u4E00\u904D\uFF0C\u628A\u5730\u57FA\u4FEE\u597D\uFF08\u6CBB\u672C\uFF09\u3002\u4F46\u662F\u73B0\u5728\u5899\u88C2\u5F97\u5FEB\u8981\u584C\u4E86\uFF08\u6807\u6025\uFF09\u2014\u2014\u4F60\u6700\u7D27\u8FEB\u7684\u662F\u7528\u67F1\u5B50\u9876\u4F4F\u5899\uFF08\u6CBB\u6807\uFF09\uFF0C\u7B49\u5B89\u5168\u4E86\u518D\u4FEE\u5730\u57FA\u3002\u6807\u672C\u7F13\u6025\u6559\u4F60\u7684\u5C31\u662F"\u4EC0\u4E48\u60C5\u51B5\u4E0B\u53EF\u4EE5\u6162\u6162\u4FEE\u5730\u57FA\uFF0C\u4EC0\u4E48\u60C5\u51B5\u4E0B\u5F97\u5148\u6253\u7D27\u6025\u652F\u6491"\u3002',
          deeperExplanation: '\u6807\u672C\u5B66\u8BF4\u662F\u4E2D\u533B\u6CBB\u7597\u51B3\u7B56\u7684\u91CD\u8981\u7406\u8BBA\u5DE5\u5177\uFF1A\uFF081\uFF09"\u672C"\u6709\u591A\u5C42\u542B\u4E49\u2014\u2014\u75C5\u56E0\u4E3A\u672C\u3001\u75C7\u72B6\u4E3A\u6807\uFF1B\u6B63\u6C14\u4E3A\u672C\u3001\u90AA\u6C14\u4E3A\u6807\uFF1B\u65E7\u75C5\u4E3A\u672C\u3001\u65B0\u75C5\u4E3A\u6807\uFF1B\u5185\u810F\u4E3A\u672C\u3001\u80A2\u4F53\u4E3A\u6807\u3002\u7406\u89E3"\u672C"\u7684\u5C42\u6B21\u6027\uFF0C\u624D\u80FD\u51C6\u786E\u5224\u65AD\u5F53\u524D\u5E94\u8BE5\u6CBB\u54EA\u4E2A"\u672C"\u3002\uFF082\uFF09\u5F20\u4EF2\u666F\u5728\u300A\u4F24\u5BD2\u8BBA\u300B\u4E2D\u5BF9\u6807\u672C\u7F13\u6025\u6709\u7CBE\u5230\u7684\u5E94\u7528\u2014\u2014\u5982"\u4E0B\u5229\u6E05\u8C37\u4E0D\u6B62\u3001\u8EAB\u4F53\u75BC\u75DB\u8005\uFF0C\u6025\u5F53\u6551\u91CC\uFF1B\u540E\u8EAB\u75BC\u75DB\u3001\u6E05\u4FBF\u81EA\u8C03\u8005\uFF0C\u6025\u5F53\u6551\u8868"\uFF08\u7B2C91\u6761\uFF09\u3002\u5F53\u91CC\u865A\u5BD2\uFF08\u4E0B\u5229\u6E05\u8C37\uFF09\u548C\u5916\u611F\u8868\u8BC1\uFF08\u8EAB\u75BC\u75DB\uFF09\u540C\u65F6\u51FA\u73B0\u65F6\uFF0C\u5FC5\u987B\u5148\u6551\u91CC\uFF08\u6E29\u9633\u6B62\u6CFB\uFF09\uFF0C\u56E0\u4E3A\u91CC\u865A\u4E0D\u6551\u53EF\u80FD\u4F1A\u5371\u53CA\u751F\u547D\uFF0C\u8868\u8BC1\u53CD\u800C\u53EF\u4EE5\u6682\u7F13\u5904\u7406\u3002\uFF083\uFF09\u6807\u672C\u540C\u6CBB\u2014\u2014\u5F53\u6807\u672C\u4FF1\u6025\u6216\u6807\u672C\u4FF1\u7F13\u65F6\uFF0C\u53EF\u4EE5\u540C\u65F6\u6CBB\u7597\u3002\u5982\u5C0F\u9752\u9F99\u6C64\u6CBB\u7597\u5916\u5BD2\u5185\u996E\uFF08\u5916\u5BD2\u4E3A\u6807\u3001\u5185\u996E\u4E3A\u672C\uFF09\uFF0C\u9EBB\u9EC4\u914D\u5E72\u59DC\u3001\u7EC6\u8F9B\uFF0C\u8868\u91CC\u53CC\u89E3\u3002\uFF084\uFF09\u540E\u4E16\u53D1\u5C55\u2014\u2014\u660E\u4EE3\u5F20\u666F\u5CB3\u63D0\u51FA"\u4EE5\u75C5\u56E0\u4E3A\u672C\u3001\u4EE5\u89C1\u8BC1\u4E3A\u6807"\u7684\u5224\u65AD\u6807\u51C6\uFF0C\u6E05\u4EE3\u53F6\u5929\u58EB\u5728\u6E29\u75C5\u6CBB\u7597\u4E2D\u8FDB\u4E00\u6B65\u53D1\u5C55\u4E86"\u5148\u5B89\u672A\u53D7\u90AA\u4E4B\u5730"\u7684\u9884\u9632\u6027\u6807\u672C\u601D\u7EF4\u3002',
          observations: [
            '\u533A\u5206"\u81F4\u547D\u6027\u75C7\u72B6"\u548C"\u975E\u81F4\u547D\u6027\u75C7\u72B6"\u2014\u2014\u5598\u4FC3\u3001\u5927\u51FA\u8840\u3001\u5267\u70C8\u75BC\u75DB\u3001\u9AD8\u70ED\u4E0D\u9000\u7B49\u53EF\u80FD\u9700\u8981\u4F18\u5148\u5904\u7406',
            "\u6CE8\u610F\u65B0\u53D1\u75C5\u548C\u65E7\u75C5\u7684\u5173\u7CFB\u2014\u2014\u65B0\u75C5\u6025\u3001\u65E7\u75C5\u7F13\uFF0C\u4F46\u4E5F\u8981\u8003\u8651\u65B0\u75C5\u662F\u5426\u4F1A\u8BF1\u53D1\u65E7\u75C5\u52A0\u91CD",
            '\u89C2\u5BDF\u6807\u672C\u4E4B\u95F4\u7684\u56E0\u679C\u5173\u7CFB\u2014\u2014\u89E3\u51B3"\u672C"\u4E4B\u540E\uFF0C"\u6807"\u662F\u5426\u968F\u4E4B\u7F13\u89E3\uFF1F\u8FD9\u53EF\u4EE5\u9A8C\u8BC1\u6807\u672C\u5224\u65AD\u662F\u5426\u6B63\u786E'
          ],
          commonMistakes: [
            '\u628A"\u6CBB\u672C"\u7B49\u540C\u4E8E"\u53EA\u7528\u8865\u836F"\u2014\u2014\u6CBB\u672C\u7684\u6838\u5FC3\u662F"\u89E3\u51B3\u6839\u672C\u75C5\u673A"\uFF0C\u5B9E\u8BC1\u7684\u6839\u672C\u75C5\u673A\u662F\u90AA\u76DB\uFF0C\u4E5F\u9700\u8981"\u6CBB\u672C"\uFF08\u795B\u90AA\uFF09',
            '\u8BA4\u4E3A"\u6CBB\u6807"\u662F"\u6C34\u5E73\u4E0D\u591F"\u7684\u8868\u73B0\u2014\u2014\u5B9E\u9645\u4E0A"\u6025\u5219\u6CBB\u6807"\u662F\u9AD8\u6C34\u5E73\u7684\u4E34\u5E8A\u51B3\u7B56\uFF0C\u4E0D\u662F\u65E0\u5948\u7684\u9009\u62E9',
            '\u5FFD\u7565"\u6807\u672C\u540C\u6CBB"\u7684\u53EF\u80FD\u6027\u2014\u2014\u4E0D\u662F\u5728"\u6CBB\u6807"\u548C"\u6CBB\u672C"\u4E4B\u95F4\u4E8C\u9009\u4E00\uFF0C\u800C\u662F\u6839\u636E\u75C5\u60C5\u9009\u62E9\u6700\u5408\u9002\u7684\u7B56\u7565'
          ],
          misconceptions: [
            '"\u672C"\u53EA\u6709\u4E00\u4E2A\u2014\u2014"\u672C"\u662F\u591A\u5C42\u6B21\u7684\uFF0C\u4E00\u4E2A\u75BE\u75C5\u53EF\u80FD\u6709\u591A\u4E2A"\u672C"\uFF08\u5982\u813E\u865A\u4E3A\u672C\u3001\u6E7F\u76DB\u4E5F\u4E3A\u672C\uFF09\uFF0C\u9700\u8981\u8FA8\u522B\u4E3B\u6B21',
            '\u6CBB\u6807\u5C31\u4E0D\u6CBB\u672C\u2014\u2014"\u6025\u5219\u6CBB\u6807"\u662F"\u5148\u6CBB\u6807"\uFF0C\u4E0D\u7B49\u4E8E"\u53EA\u6CBB\u6807"\uFF0C\u6807\u8BC1\u7F13\u89E3\u540E\u4ECD\u8981\u56DE\u5230\u6CBB\u672C',
            "\u6025\u75C7\u624D\u9700\u8981\u8003\u8651\u6807\u672C\u2014\u2014\u6162\u6027\u75C5\u7BA1\u7406\u4E2D\u540C\u6837\u5B58\u5728\u6807\u672C\u7F13\u6025\u7684\u5224\u65AD\uFF08\u5982\u5148\u7F13\u89E3\u75BC\u75DB\u518D\u8C03\u7406\u4F53\u8D28\uFF09"
          ],
          classicReferences: ["\u7D20\u95EE-\u9634\u9633\u5E94\u8C61\u5927\u8BBA", "\u4F24\u5BD2\u8BBA-\u8FA8\u592A\u9633\u75C5\u8109\u8BC1\u5E76\u6CBB", "\u666F\u5CB3\u5168\u4E66-\u6807\u672C\u8BBA"],
          formulaReferences: ["\u5C0F\u9752\u9F99\u6C64", "\u771F\u6B66\u6C64", "\u56DB\u9006\u6C64", "\u9EBB\u9EC4\u7EC6\u8F9B\u9644\u5B50\u6C64"],
          paradoxIds: [],
