          parentNodeId: null,
          childrenIds: ["v3-s7-n4"],
          coreConcept: "\u6B63\u6CBB\u662F\u836F\u6027\u4E0E\u75C5\u6027\u76F8\u53CD\uFF08\u70ED\u8005\u5BD2\u4E4B\uFF09\uFF0C\u53CD\u6CBB\u662F\u987A\u4ECE\u5047\u8C61\u6CBB\u672C\u8D28\uFF08\u70ED\u56E0\u70ED\u7528\u4E8E\u771F\u5BD2\u5047\u70ED\uFF09\u3002\u53CD\u6CBB\u7684\u672C\u8D28\u4ECD\u662F\u6B63\u6CBB\u3002",
          whyItMatters: '\u6B63\u6CBB\u53CD\u6CBB\u8BAD\u7EC3\u7684\u662F"\u4E0D\u88AB\u8868\u8C61\u8FF7\u60D1"\u7684\u6DF1\u5C42\u8FA8\u8BC1\u80FD\u529B\u3002\u533A\u5206"\u771F\u5BD2\u5047\u70ED"\u548C"\u771F\u70ED\u5047\u5BD2"\u662F\u4E2D\u533B\u4E34\u5E8A\u7684\u6700\u9AD8\u96BE\u5EA6\u4E4B\u4E00\uFF0C\u4E5F\u662F\u4E2D\u533B\u8FA8\u8BC1\u7684"\u8BD5\u91D1\u77F3"\u3002',
          beginnerExplanation: '\u6B63\u6CBB\u5C31\u50CF"\u706D\u706B"\u2014\u2014\u7740\u706B\u4E86\uFF08\u70ED\u8BC1\uFF09\u5C31\u7528\u6C34\u6D47\uFF08\u5BD2\u836F\uFF09\uFF1B\u89C9\u5F97\u51B7\uFF08\u5BD2\u8BC1\uFF09\u5C31\u751F\u706B\u53D6\u6696\uFF08\u70ED\u836F\uFF09\u3002\u8FD9\u5F88\u76F4\u89C9\u3002\u53CD\u6CBB\u5C31\u50CF\u4E00\u4E2A"\u4F2A\u88C5"\u7684\u573A\u666F\uFF1A\u4E00\u4E2A\u4EBA\u660E\u660E\u51BB\u5F97\u53D1\u6296\uFF08\u771F\u5BD2\uFF09\uFF0C\u4F46\u8138\u4E0A\u5374\u7EA2\u6251\u6251\u7684\u50CF\u559D\u9189\u4E86\u9152\uFF08\u5047\u70ED\uFF09\u3002\u5982\u679C\u4F60\u770B\u5230\u4ED6\u8138\u7EA2\u5C31\u53BB\u7ED9\u4ED6\u6247\u98CE\u964D\u6E29\uFF08\u7528\u5BD2\u836F\uFF09\uFF0C\u90A3\u5C31\u5B8C\u86CB\u4E86\u2014\u2014\u4ED6\u4F1A\u51BB\u5F97\u66F4\u5389\u5BB3\u3002\u6B63\u786E\u7684\u505A\u6CD5\u662F\uFF1A\u770B\u5230\u4ED6\u8138\u7EA2\u7684"\u5047\u8C61"\u4E0B\u9762\u7684"\u771F\u76F8"\uFF08\u51BB\u7740\u4E86\uFF09\u2014\u2014\u7ED9\u4ED6\u751F\u706B\u53D6\u6696\uFF08\u7528\u70ED\u836F\uFF09\u3002\u53CD\u6CBB\u4E0D\u662F"\u6545\u610F\u53CD\u7740\u6765"\uFF0C\u800C\u662F"\u63ED\u7A7F\u75C5\u60C5\u7684\u4F2A\u88C5\uFF0C\u771F\u76F8\u662F\u4EC0\u4E48\u5C31\u600E\u4E48\u6CBB"\u3002',
          deeperExplanation: '\u6B63\u6CBB\u4E0E\u53CD\u6CBB\u7684\u7406\u8BBA\u4F53\u7CFB\uFF1A\uFF081\uFF09\u6B63\u6CBB\uFF08\u9006\u6CBB\uFF09\u2014\u2014"\u5BD2\u8005\u70ED\u4E4B\u3001\u70ED\u8005\u5BD2\u4E4B\u3001\u865A\u8005\u8865\u4E4B\u3001\u5B9E\u8005\u6CFB\u4E4B"\uFF0C\u662F\u6700\u5E38\u89C4\u3001\u6700\u5E38\u7528\u7684\u6CBB\u7597\u7B56\u7565\uFF0C\u9002\u7528\u4E8E\u75C5\u60C5\u5355\u7EAF\u3001\u8868\u8C61\u4E0E\u672C\u8D28\u4E00\u81F4\u7684\u60C5\u51B5\u3002\uFF082\uFF09\u53CD\u6CBB\uFF08\u4ECE\u6CBB\uFF09\u2014\u2014"\u70ED\u56E0\u70ED\u7528\u3001\u5BD2\u56E0\u5BD2\u7528\u3001\u585E\u56E0\u585E\u7528\u3001\u901A\u56E0\u901A\u7528"\uFF0C\u9002\u7528\u4E8E\u75C5\u60C5\u590D\u6742\u3001\u8868\u8C61\u4E0E\u672C\u8D28\u4E0D\u4E00\u81F4\u7684\u60C5\u51B5\u3002"\u70ED\u56E0\u70ED\u7528"\u662F\u7528\u70ED\u836F\u6CBB\u7597\u5047\u70ED\u8BC1\uFF08\u771F\u5BD2\u5047\u70ED\uFF09\uFF0C\u5982\u901A\u8109\u56DB\u9006\u6C64\u3002"\u5BD2\u56E0\u5BD2\u7528"\u662F\u7528\u5BD2\u836F\u6CBB\u7597\u5047\u5BD2\u8BC1\uFF08\u771F\u70ED\u5047\u5BD2\uFF09\uFF0C\u5982\u767D\u864E\u6C64\u6CBB\u7597\u70ED\u53A5\uFF08\u70ED\u90AA\u5185\u4F0F\u3001\u56DB\u80A2\u53A5\u51B7\uFF09\u3002"\u585E\u56E0\u585E\u7528"\u662F\u7528\u8865\u6CD5\u6CBB\u7597\u5047\u5B9E\uFF08\u771F\u865A\u5047\u5B9E\u2014\u2014\u5982\u813E\u865A\u8179\u80C0\u7528\u8865\u4E2D\u76CA\u6C14\u6C64\uFF0C\u4E0D\u662F\u7528\u7406\u6C14\u6D88\u5BFC\u836F\uFF09\u3002"\u901A\u56E0\u901A\u7528"\u662F\u7528\u6CFB\u6CD5\u6CBB\u7597\u5047\u865A\uFF08\u771F\u5B9E\u5047\u865A\u2014\u2014\u5982\u70ED\u7ED3\u65C1\u6D41\u7528\u627F\u6C14\u6C64\u653B\u4E0B\uFF09\u3002\uFF083\uFF09\u53CD\u6CBB\u7684\u9274\u522B\u8981\u70B9\u2014\u2014\u5173\u952E\u5728\u4E8E"\u8109\u8C61"\u548C"\u820C\u8C61"\uFF1A\u771F\u5BD2\u5047\u70ED\u7684\u8109\u6D6E\u5927\u65E0\u6839\u3001\u820C\u6DE1\u80D6\u5AE9\uFF1B\u771F\u70ED\u5047\u5BD2\u7684\u8109\u6C89\u5B9E\u6709\u529B\u3001\u820C\u7EA2\u82D4\u9EC4\u71E5\u3002\u53E6\u5916\uFF0C\u5047\u70ED\u901A\u5E38\u8868\u73B0\u4E3A"\u5934\u9762\u70ED\u800C\u56DB\u80A2\u51B7\u3001\u53E3\u5E72\u800C\u4E0D\u6B32\u996E\u3001\u6216\u559C\u70ED\u996E"\u2014\u2014\u8FD9\u4E9B\u7EBF\u7D22\u90FD\u9700\u8981\u7EFC\u5408\u5224\u65AD\u3002\uFF084\uFF09\u540E\u4E16\u53D1\u5C55\u2014\u2014\u660E\u4EE3\u5F20\u666F\u5CB3\u5C06\u6B63\u6CBB\u53CD\u6CBB\u8FDB\u4E00\u6B65\u7EC6\u5206\u4E3A"\u6B63\u6CBB\u516B\u6CD5"\u548C"\u4ECE\u6CBB\u516B\u6CD5"\uFF0C\u6E05\u4EE3\u4FDE\u5609\u8A00\u5219\u5728\u300A\u533B\u95E8\u6CD5\u5F8B\u300B\u4E2D\u5F3A\u8C03"\u8FA8\u8BC1\u987B\u8FA8\u771F\u5047\uFF0C\u7528\u836F\u987B\u77E5\u9006\u4ECE"\u3002',
          observations: [
            '\u6CE8\u610F"\u5047\u70ED"\u7684\u7EC6\u5FAE\u7EBF\u7D22\uFF1A\u9762\u8272\u6CDB\u7EA2\u5982\u5986\uFF08\u4E0D\u662F\u6EE1\u9762\u901A\u7EA2\uFF09\uFF0C\u53E3\u5E72\u4F46\u4E0D\u6B32\u996E\u6216\u559C\u70ED\u996E\uFF0C\u8109\u6D6E\u5927\u4F46\u6309\u4E4B\u65E0\u529B',
            '\u89C2\u5BDF"\u4E0A\u4E0B\u4E0D\u4E00\u81F4"\u7684\u8868\u73B0\uFF1A\u4E0A\u70ED\uFF08\u9762\u7EA2\u3001\u53E3\u5E72\uFF09\u4E0B\u5BD2\uFF08\u8DB3\u51B7\u3001\u5C0F\u4FBF\u6E05\u957F\uFF09\u5F80\u5F80\u662F\u771F\u5BD2\u5047\u70ED',
            '\u6CE8\u610F"\u8109\u8BC1\u4E0D\u7B26"\u7684\u60C5\u51B5\u2014\u2014\u8109\u8C61\u548C\u75C7\u72B6\u4E0D\u4E00\u81F4\u65F6\uFF0C\u901A\u5E38"\u820D\u8BC1\u4ECE\u8109"'
          ],
          commonMistakes: [
            '\u770B\u5230"\u70ED\u8C61"\u5C31\u6E05\u70ED\u2014\u2014\u6CA1\u6709\u68C0\u67E5\u662F\u5426\u5B58\u5728"\u5047\u70ED"\u7684\u53EF\u80FD',
            '\u8BA4\u4E3A"\u53CD\u6CBB"\u53EA\u6709\u70ED\u56E0\u70ED\u7528\u2014\u2014\u53CD\u6CBB\u5305\u62EC\u56DB\u79CD\uFF1A\u70ED\u56E0\u70ED\u7528\u3001\u5BD2\u56E0\u5BD2\u7528\u3001\u585E\u56E0\u585E\u7528\u3001\u901A\u56E0\u901A\u7528',
            '\u628A"\u5047\u70ED"\u8BEF\u5224\u4E3A"\u771F\u70ED"\u2014\u2014\u5047\u70ED\u7684\u7279\u70B9\u662F\u5C40\u90E8\u70ED\uFF08\u5934\u9762\uFF09\u3001\u5168\u8EAB\u51B7\uFF08\u56DB\u80A2\uFF09\uFF0C\u771F\u70ED\u662F\u5168\u8EAB\u6027\u70ED'
          ],
          misconceptions: [
            '\u53CD\u6CBB\u662F\u548C\u6B63\u6CBB"\u76F8\u53CD"\u7684\u65B9\u6CD5\u2014\u2014\u53CD\u6CBB\u7684\u672C\u8D28\u4ECD\u7136\u662F\u6B63\u6CBB\uFF08\u9488\u5BF9\u672C\u8D28\uFF09\uFF0C\u53EA\u662F\u591A\u4E86\u4E00\u5C42"\u900F\u8FC7\u5047\u8C61"\u7684\u8FA8\u522B',
            "\u53CD\u6CBB\u5F88\u5C11\u7528\u5230\u2014\u2014\u5728\u590D\u6742\u5185\u79D1\u75BE\u75C5\u4E2D\uFF0C\u771F\u5047\u4E92\u89C1\u7684\u60C5\u51B5\u975E\u5E38\u5E38\u89C1\uFF0C\u53CD\u6CBB\u601D\u7EF4\u51E0\u4E4E\u6BCF\u5929\u90FD\u4F1A\u7528\u5230",
            '"\u70ED\u56E0\u70ED\u7528"\u5C31\u662F\u7528\u70ED\u836F\u6CBB\u7597\u53D1\u70ED\u2014\u2014\u9519\uFF0C\u662F\u7528\u70ED\u836F\u6CBB\u7597"\u5047\u70ED"\uFF0C\u771F\u70ED\u7528\u70ED\u836F\u5C31\u662F\u706B\u4E0A\u6D47\u6CB9'
          ],
          classicReferences: ["\u7D20\u95EE-\u81F3\u771F\u8981\u5927\u8BBA", "\u4F24\u5BD2\u8BBA-\u8FA8\u5C11\u9634\u75C5\u8109\u8BC1\u5E76\u6CBB", "\u666F\u5CB3\u5168\u4E66-\u9006\u4ECE\u8BBA"],
          formulaReferences: ["\u901A\u8109\u56DB\u9006\u6C64", "\u767D\u901A\u6C64", "\u767D\u864E\u6C64", "\u8865\u4E2D\u76CA\u6C14\u6C64"],
